/* Canvas renderer: water, canyon light, motes, scene composition. */
import {
  TAU, clamp, lerp, mixColor, rgba, wobble, RNG, easeOutCubic,
} from './utils.js';
import { ZONES, WORLD, paletteAt, zoneAt } from './world.js';
import { drawReef, drawKelp, drawCoral, drawVent, drawRuin, drawBeacon, drawChest, drawResource } from './render-environment.js';
import { drawCreature, drawAmbientJelly } from './render-creatures.js';
import { drawPlayer, drawHeadlight } from './render-player.js';

const ZONE_BY_ID = new Map(ZONES.map(z => [z.id, z]));

export class OceanRenderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.W = 0; this.H = 0; this.dpr = 1; this.zoom = 1;
    this.time = 0;
    this.pal = ZONES[0].palette;
    this.glowCache = new Map();
    this.motes = [];
    this.frameFronds = [];
    this.camera = { x: WORLD.spawn.x, y: WORLD.spawn.y, shakeX: 0, shakeY: 0 };
    this.game = null;
    this._initMotes();
    this._initFrameFronds();
    this.resize();
  }

  resize() {
    const W = window.innerWidth || document.documentElement.clientWidth;
    const H = window.innerHeight || document.documentElement.clientHeight;
    this.W = W; this.H = H;
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width = Math.round(W * this.dpr);
    this.canvas.height = Math.round(H * this.dpr);
    this.canvas.style.width = W + 'px';
    this.canvas.style.height = H + 'px';
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.zoom = W / H < 0.88
      ? clamp(W / 560, 0.62, 0.9)
      : clamp(Math.min(W / 1360, H / 800), 0.7, 1.06);
  }

  _initMotes() {
    const rng = new RNG(4871);
    for (let i = 0; i < 150; i++) {
      this.motes.push({
        x: rng.next(), y: rng.next(), z: rng.range(0.25, 1),
        size: rng.range(0.5, 2.3), phase: rng.range(0, TAU),
        speed: rng.range(0.35, 1.4), glow: rng.chance(0.07),
      });
    }
  }

  _initFrameFronds() {
    const rng = new RNG(991);
    for (let i = 0; i < 12; i++) {
      this.frameFronds.push({
        side: i % 2 === 0 ? -1 : 1,
        x: rng.range(0.02, 0.2),
        height: rng.range(0.18, 0.46),
        lean: rng.range(-0.2, 0.2),
        phase: rng.range(0, TAU),
        width: rng.range(1.2, 3.4),
        leaves: rng.int(3, 6),
        dark: rng.range(0.35, 0.85),
      });
    }
  }

  /* ---------- transforms and shared helpers ---------- */
  screen(x, y, p = 1) {
    const cam = this.camera;
    return [
      (x - cam.x * p) * this.zoom + this.W / 2 + cam.shakeX,
      (y - cam.y * p) * this.zoom + this.H / 2 + cam.shakeY,
    ];
  }

  visible(x, y, pad = 260, p = 1) {
    const [sx, sy] = this.screen(x, y, p);
    return sx > -pad && sx < this.W + pad && sy > -pad && sy < this.H + pad;
  }

  palFor(zoneId) {
    return (ZONE_BY_ID.get(zoneId) || ZONES[0]).palette;
  }

  getGlow(color) {
    let c = this.glowCache.get(color);
    if (c) return c;
    const size = 128;
    const cv = document.createElement('canvas');
    cv.width = size; cv.height = size;
    const g = cv.getContext('2d');
    const grad = g.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
    grad.addColorStop(0, rgba(color, 0.95));
    grad.addColorStop(0.24, rgba(color, 0.48));
    grad.addColorStop(0.58, rgba(color, 0.12));
    grad.addColorStop(1, rgba(color, 0));
    g.fillStyle = grad;
    g.fillRect(0, 0, size, size);
    this.glowCache.set(color, cv);
    return cv;
  }

  drawGlow(x, y, color, radius, alpha = 1) {
    const glow = this.getGlow(color);
    const ctx = this.ctx;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.globalCompositeOperation = 'lighter';
    ctx.drawImage(glow, x - radius, y - radius, radius * 2, radius * 2);
    ctx.restore();
  }

  blobPath(cx, cy, rx, ry, seed, points = 13, rough = 0.17) {
    const ctx = this.ctx;
    ctx.beginPath();
    for (let i = 0; i < points; i++) {
      const a = (i / points) * TAU;
      const n = 1 + rough * (Math.sin(seed * 0.91 + i * 2.71) * 0.65 + Math.sin(seed * 1.73 + i * 5.13) * 0.35);
      const px = cx + Math.cos(a) * rx * n;
      const py = cy + Math.sin(a) * ry * n;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }

  roundRect(x, y, w, h, r) {
    const ctx = this.ctx;
    const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
    ctx.closePath();
  }

  /* ---------- main draw ---------- */
  render(game) {
    const ctx = this.ctx;
    this.time = game.time;
    this.game = game;
    this.camera = game.camera;
    this.pal = paletteAt(game.camera.y);

    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';

    this.drawWater();
    this.drawBackdrop();
    this.drawRays();
    this.drawMotes();

    this.drawDecor('back');
    this.drawDecor('mid');

    for (const chest of game.chests) if (this.visible(chest.x, chest.y, 140)) drawChest(this, chest, game);
    for (const res of game.resources) if (!res.collected && this.visible(res.x, res.y, 100)) drawResource(this, res, game);

    this.drawHeadlightIfAny();

    const drawables = [];
    for (const c of game.creatures) {
      if (!this.visible(c.x, c.y, 340)) continue;
      drawables.push({ y: c.y, kind: 'creature', c });
    }
    if (game.mode !== 'title' || game.titleSub) {
      drawables.push({ y: game.player.y, kind: 'player' });
    }
    drawables.sort((a, b) => a.y - b.y);
    for (const d of drawables) {
      if (d.kind === 'creature') drawCreature(this, d.c);
      else drawPlayer(this, game);
    }

    this.drawBubbles(game.bubbles);
    this.drawDecor('fg');
    this.drawFrameFronds();
    this.drawParticles(game.particles);
    this.drawPulse(game);
    this.drawScreenFx(game);
  }

  drawHeadlightIfAny() {
    if (this.game.mode !== 'playing' && this.game.mode !== 'title') return;
    if (!this.game.player?.lightsOn) return;
    drawHeadlight(this, this.game);
  }

  /* ---------- water & atmosphere ---------- */
  drawWater() {
    const ctx = this.ctx, W = this.W, H = this.H, pal = this.pal;
    const zone = zoneAt(this.camera.y);
    const light = clamp(zone.light * (1 - clamp((this.camera.y - 500) / 6200, 0, 0.5)), 0, 1);
    const grad = ctx.createLinearGradient(0, 0, 0, H);
    grad.addColorStop(0, pal.top);
    grad.addColorStop(0.38, pal.mid);
    grad.addColorStop(0.74, mixColor(pal.mid, pal.bottom, 0.72));
    grad.addColorStop(1, pal.bottom);
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);

    // Broad surface bloom.
    if (light > 0.03) {
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      const glow = ctx.createRadialGradient(W * 0.5, -H * 0.12, 0, W * 0.5, -H * 0.12, H * 1.18);
      glow.addColorStop(0, rgba(pal.rim, 0.3 * light));
      glow.addColorStop(0.34, rgba(pal.fog, 0.11 * light));
      glow.addColorStop(1, rgba(pal.fog, 0));
      ctx.fillStyle = glow;
      ctx.fillRect(0, 0, W, H);
      ctx.restore();
    }

    // Cool rim at the edges of the water column.
    const side = ctx.createLinearGradient(0, 0, W, 0);
    side.addColorStop(0, 'rgba(0,5,12,.22)');
    side.addColorStop(0.15, 'rgba(0,5,12,0)');
    side.addColorStop(0.85, 'rgba(0,5,12,0)');
    side.addColorStop(1, 'rgba(0,5,12,.24)');
    ctx.fillStyle = side;
    ctx.fillRect(0, 0, W, H);

    this.drawSurface();
    this.drawBioHaze();
  }

  drawSurface() {
    const ctx = this.ctx;
    const sy = (WORLD.surface - this.camera.y) * this.zoom + this.H / 2 + this.camera.shakeY;
    if (sy < -90 || sy > this.H * 0.72) return;
    const sky = ctx.createLinearGradient(0, Math.min(-200, sy - 300), 0, sy + 10);
    sky.addColorStop(0, '#c4f5fa');
    sky.addColorStop(0.62, '#8fe3ee');
    sky.addColorStop(1, '#63c8dc');
    ctx.fillStyle = sky;
    ctx.fillRect(0, -400, this.W, Math.max(0, sy + 400));
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    for (let i = 0; i < 5; i++) {
      const y = sy - (i + 1) * 14;
      ctx.beginPath();
      for (let x = -20; x <= this.W + 20; x += 20) {
        const yy = y + Math.sin(x * 0.018 + this.time * 1.2 + i * 1.3) * (7 - i * 0.8);
        if (x === -20) ctx.moveTo(x, yy); else ctx.lineTo(x, yy);
      }
      ctx.strokeStyle = `rgba(226,255,255,${0.26 - i * 0.04})`;
      ctx.lineWidth = 1.4;
      ctx.stroke();
    }
    const glint = ctx.createLinearGradient(0, sy - 120, 0, sy + 20);
    glint.addColorStop(0, 'rgba(226,255,255,0)');
    glint.addColorStop(0.6, 'rgba(226,255,255,.13)');
    glint.addColorStop(1, 'rgba(120,240,238,.2)');
    ctx.fillStyle = glint;
    ctx.fillRect(0, sy - 120, this.W, 135);
    ctx.restore();
  }

  drawBioHaze() {
    if (this.camera.y < 2400) return;
    const ctx = this.ctx, W = this.W, H = this.H, pal = this.pal;
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    for (let i = 0; i < 3; i++) {
      const x = W * (0.2 + i * 0.32) + Math.sin(this.time * 0.05 + i * 2.2) * 90;
      const y = H * (0.32 + 0.2 * Math.sin(i * 2.7 + this.time * 0.03));
      const r = H * (0.34 + i * 0.12);
      const g = ctx.createRadialGradient(x, y, 0, x, y, r);
      g.addColorStop(0, rgba(pal.accent, 0.035));
      g.addColorStop(0.5, rgba(pal.fog, 0.018));
      g.addColorStop(1, rgba(pal.fog, 0));
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
    }
    ctx.restore();
  }

  drawBackdrop() {
    this.drawCanyon();
    this.drawDistantRidges();

    for (const jelly of this.game.world.ambientJellies) {
      if (!this.visible(jelly.x, jelly.y, 300, jelly.parallax)) continue;
      drawAmbientJelly(this, jelly);
    }

    // A very distant survey whale, only in the deeper half of the ocean.
    if (this.camera.y > 2500) this.drawWhale();
  }

  drawCanyon() {
    const ctx = this.ctx, W = this.W, H = this.H, pal = this.pal;
    const camY = this.camera.y, camX = this.camera.x;
    const drawWall = (side, layers) => {
      for (const layer of layers) {
        const pts = [];
        const steps = 18;
        for (let i = 0; i <= steps; i++) {
          const yy = i / steps * H;
          const worldY = camY - H / 2 + yy;
          const n = wobble(worldY * 0.012 + side * 13.7, side * 2.3 + layer.seed);
          const bulge = Math.sin(worldY * 0.0021 + layer.seed) * layer.amp * 0.45;
          const edge = layer.base + (n * 0.5 + 0.5) * layer.amp + bulge + (camX - WORLD.spawn.x) * 0.018;
          const x = side < 0 ? edge * W : W - edge * W;
          pts.push([x, yy]);
        }
        ctx.beginPath();
        if (side < 0) {
          ctx.moveTo(-5, -5);
          for (const [x, y] of pts) ctx.lineTo(x, y);
          ctx.lineTo(-5, H + 5);
        } else {
          ctx.moveTo(W + 5, -5);
          for (const [x, y] of pts) ctx.lineTo(x, y);
          ctx.lineTo(W + 5, H + 5);
        }
        ctx.closePath();
        const g = ctx.createLinearGradient(side < 0 ? 0 : W, 0, side < 0 ? W * 0.3 : W * 0.7, 0);
        g.addColorStop(0, rgba(layer.color, layer.alpha));
        g.addColorStop(0.55, rgba(layer.color, layer.alpha * 0.62));
        g.addColorStop(1, rgba(layer.color, 0));
        ctx.fillStyle = g;
        ctx.fill();

        // Rim lighting along the jagged edge.
        if (layer.rim > 0) {
          ctx.beginPath();
          pts.forEach(([x, y], i) => { if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y); });
          ctx.strokeStyle = rgba(pal.rim, layer.rim);
          ctx.lineWidth = 1.4;
          ctx.stroke();
        }

        // Little rock shelves and cold bioluminescence on the wall.
        if (layer.shelves) {
          for (let i = 1; i < pts.length - 1; i += 3) {
            const [x, y] = pts[i];
            const w = (side < 0 ? 1 : -1) * (12 + (i % 4) * 9);
            ctx.beginPath();
            ctx.moveTo(x, y + 2);
            ctx.lineTo(x - w * 0.75, y + 20);
            ctx.lineTo(x - w * 0.1, y + 13);
            ctx.closePath();
            ctx.fillStyle = rgba(layer.color, layer.alpha * 0.65);
            ctx.fill();
            if ((i + layer.seed) % 5 === 0) {
              const gx = x + (side < 0 ? 16 : -16);
              const gy = y + 26;
              ctx.fillStyle = rgba(pal.accent, 0.24);
              ctx.beginPath(); ctx.arc(gx, gy, 1.6, 0, TAU); ctx.fill();
              if (this.camera.y > 2800) this.drawGlow(gx, gy, pal.accent, 12, 0.4);
            }
          }
        }
      }
    };

    const fog = mixColor(pal.fog, pal.bottom, 0.55);
    const near = mixColor(pal.rockBottom, '#000000', 0.22);
    drawWall(-1, [
      { base: 0.13, amp: 0.055, color: fog, alpha: 0.24, rim: 0.035, seed: 1.1, shelves: false },
      { base: 0.075, amp: 0.05, color: near, alpha: 0.55, rim: 0.07, seed: 4.4, shelves: true },
    ]);
    drawWall(1, [
      { base: 0.16, amp: 0.06, color: fog, alpha: 0.2, rim: 0.03, seed: 7.7, shelves: false },
      { base: 0.086, amp: 0.045, color: near, alpha: 0.52, rim: 0.065, seed: 2.8, shelves: true },
    ]);
  }

  drawDistantRidges() {
    const ctx = this.ctx, W = this.W, H = this.H, pal = this.pal;
    const drawRidge = (baseline, amp, color, alpha, seed) => {
      ctx.beginPath();
      ctx.moveTo(-20, H + 30);
      for (let x = -20; x <= W + 20; x += 26) {
        const wx = this.camera.x + (x - W / 2) / this.zoom;
        const n = wobble(wx * 0.006 + seed, seed * 1.7) * 0.5 + 0.5;
        const sway = Math.sin(this.camera.y * 0.0008 + seed) * 22;
        const y = baseline - n * amp + sway;
        ctx.lineTo(x, y);
      }
      ctx.lineTo(W + 20, H + 30);
      ctx.closePath();
      ctx.fillStyle = rgba(color, alpha);
      ctx.fill();
    };
    drawRidge(H * 0.88, H * 0.3, mixColor(pal.rockBottom, '#000', 0.15), 0.3, 2.2);
    drawRidge(H * 0.94, H * 0.25, mixColor(pal.rockBottom, '#000', 0.4), 0.45, 5.1);

    // Slow, enormous whale silhouette.
  }

  drawWhale() {
    const ctx = this.ctx, W = this.W;
    const t = this.time * 0.008;
    const x = ((t * 40 + 260) % (W + 1100)) - 500;
    const y = this.H * 0.28 + Math.sin(this.time * 0.07) * 26;
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(1.4, 1.4);
    ctx.globalAlpha = 0.045;
    ctx.fillStyle = '#04121f';
    ctx.beginPath();
    ctx.moveTo(-180, 0);
    ctx.bezierCurveTo(-120, -36, 80, -44, 170, -8);
    ctx.bezierCurveTo(196, 2, 188, 18, 150, 22);
    ctx.bezierCurveTo(40, 32, -90, 26, -180, 8);
    ctx.closePath();
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(160, -4); ctx.lineTo(208, -30); ctx.lineTo(198, 18); ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  drawRays() {
    const ctx = this.ctx, W = this.W, H = this.H, pal = this.pal;
    const zone = zoneAt(this.camera.y);
    const light = zone.light * clamp(1 - (this.camera.y - 300) / 5200, 0, 1);
    if (light < 0.035) return;
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const count = 7;
    for (let i = 0; i < count; i++) {
      const base = (i + 0.4) / count * W + Math.sin(this.time * 0.055 + i * 1.73) * 28;
      const topW = 14 + (i % 3) * 10;
      const botW = 130 + (i % 4) * 48;
      const tilt = 150 + i * 16;
      const alpha = (0.04 + 0.05 * (0.5 + 0.5 * Math.sin(this.time * 0.23 + i * 2.1))) * light;
      const g = ctx.createLinearGradient(base, -30, base + tilt, H);
      g.addColorStop(0, rgba(pal.rim, alpha * 1.8));
      g.addColorStop(0.4, rgba(pal.rim, alpha * 0.7));
      g.addColorStop(1, rgba(pal.rim, 0));
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.moveTo(base - topW, -40);
      ctx.lineTo(base + topW, -40);
      ctx.lineTo(base + tilt + botW, H + 40);
      ctx.lineTo(base + tilt - botW, H + 40);
      ctx.closePath();
      ctx.fill();
    }
    // Caustic ribbons just below the sun.
    if (this.camera.y < 1700) {
      for (let i = 0; i < 4; i++) {
        ctx.beginPath();
        for (let x = -20; x <= W + 20; x += 24) {
          const y = H * (0.08 + i * 0.07) + Math.sin(x * 0.011 + this.time * 0.6 + i * 1.9) * 13 + Math.sin(x * 0.03 - this.time * 0.4) * 4;
          if (x === -20) ctx.moveTo(x, y); else ctx.lineTo(x, y);
        }
        ctx.strokeStyle = rgba(pal.rim, 0.02 * light);
        ctx.lineWidth = 1.2;
        ctx.stroke();
      }
    }
    ctx.restore();
  }

  drawMotes() {
    const ctx = this.ctx, W = this.W, H = this.H, pal = this.pal;
    const deep = clamp((this.camera.y - 1800) / 3400, 0, 1);
    const cam = this.camera;
    ctx.save();
    for (const m of this.motes) {
      const drift = this.time * m.speed;
      const x = ((m.x * W + drift * 5 + Math.sin(this.time * 0.24 + m.phase) * 14 - cam.x * 0.018 * m.z) % (W + 60) + W + 60) % (W + 60) - 30;
      const y = ((m.y * H + drift * 3.2 + Math.sin(this.time * 0.17 + m.phase * 2) * 9 - cam.y * 0.035 * m.z) % (H + 60) + H + 60) % (H + 60) - 30;
      const a = (0.1 + 0.42 * m.z) * (0.45 + deep * 0.55);
      const col = deep > 0.35 ? (m.glow ? pal.accent : pal.particle) : pal.particle;
      ctx.fillStyle = rgba(col, a);
      ctx.beginPath();
      ctx.arc(x, y, m.size * (0.55 + m.z * 0.75), 0, TAU);
      ctx.fill();
      if (m.glow && deep > 0.3) this.drawGlow(x, y, col, 10 + m.z * 12, a * 0.55);
    }
    ctx.restore();
  }

  /* ---------- scenery ---------- */
  drawDecor(layer) {
    const list = this.game.world.decor;
    const p = layer === 'fg' ? 1.055 : layer === 'back' ? 0.992 : 1;
    const visible = [];
    for (const obj of list) {
      if ((obj.layer || 'mid') !== layer) continue;
      if (!this.visible(obj.x, obj.y, layer === 'fg' ? 420 : 300, p)) continue;
      visible.push(obj);
    }
    visible.sort((a, b) => a.y - b.y);
    if (layer === 'fg') this.ctx.save();
    for (const obj of visible) {
      switch (obj.type) {
        case 'reef': drawReef(this, obj, p, layer === 'fg'); break;
        case 'kelp': drawKelp(this, obj, p, layer === 'fg'); break;
        case 'coral': drawCoral(this, obj, p); break;
        case 'vent': drawVent(this, obj, p); break;
        case 'ruin': drawRuin(this, obj, p); break;
        case 'beacon': drawBeacon(this, obj, p); break;
        default: break;
      }
    }
    if (layer === 'fg') this.ctx.restore();
  }

  drawBubbles(bubbles) {
    const ctx = this.ctx;
    for (const b of bubbles) {
      const [sx, sy] = this.screen(b.x, b.y);
      if (sx < -30 || sx > this.W + 30 || sy < -30 || sy > this.H + 30) continue;
      const r = Math.max(0.7, b.r * this.zoom);
      const a = clamp(b.life / b.maxLife, 0, 1) * (b.alpha ?? 0.65);
      ctx.save();
      ctx.globalAlpha = a;
      ctx.beginPath();
      ctx.arc(sx, sy, r, 0, TAU);
      ctx.fillStyle = b.kind === 'spark' ? rgba(b.color || '#c9ffff', 0.12) : 'rgba(185,245,255,0.08)';
      ctx.fill();
      ctx.strokeStyle = b.color ? rgba(b.color, 0.55) : 'rgba(210,252,255,0.5)';
      ctx.lineWidth = Math.max(0.7, r * 0.16);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(sx - r * 0.3, sy - r * 0.35, Math.max(0.4, r * 0.2), 0, TAU);
      ctx.fillStyle = 'rgba(255,255,255,.7)';
      ctx.fill();
      ctx.restore();
    }
  }

  drawParticles(particles) {
    const ctx = this.ctx;
    for (const p of particles) {
      const [sx, sy] = this.screen(p.x, p.y);
      if (sx < -80 || sx > this.W + 80 || sy < -80 || sy > this.H + 80) continue;
      const t = clamp(p.life / p.maxLife, 0, 1);
      if (p.type === 'text') {
        ctx.save();
        ctx.globalAlpha = Math.min(1, t * 2.4);
        ctx.font = `700 ${p.size || 11}px Manrope, sans-serif`;
        ctx.textAlign = 'center';
        ctx.fillStyle = p.color || '#eaffff';
        ctx.shadowColor = 'rgba(0,5,10,.85)';
        ctx.shadowBlur = 6;
        ctx.fillText(p.text, sx, sy - (1 - t) * 28);
        ctx.restore();
      } else if (p.type === 'ring') {
        ctx.save();
        ctx.globalAlpha = t * 0.75;
        ctx.strokeStyle = p.color || '#86fff1';
        ctx.lineWidth = p.line || 2;
        const r = (1 - t) * p.radius + 4;
        ctx.beginPath(); ctx.arc(sx, sy, r, 0, TAU); ctx.stroke();
        ctx.restore();
      } else if (p.type === 'smoke') {
        ctx.save();
        ctx.globalAlpha = t * 0.35;
        ctx.fillStyle = p.color || '#0a1a24';
        ctx.beginPath(); ctx.arc(sx, sy, (1 - t) * p.size + 2, 0, TAU); ctx.fill();
        ctx.restore();
      } else {
        const col = p.color || '#d8ffff';
        const size = p.size * (p.shrink === false ? 1 : (0.3 + t * 0.7));
        if (size > 3.5) this.drawGlow(sx, sy, col, size * 3.4, 0.32 * t);
        ctx.save();
        ctx.globalAlpha = t;
        ctx.fillStyle = col;
        ctx.beginPath();
        if (p.type === 'shard') {
          ctx.translate(sx, sy);
          ctx.rotate(p.angle || 0);
          ctx.rect(-size * 0.35, -size, size * 0.7, size * 2);
        } else {
          ctx.arc(sx, sy, Math.max(0.5, size), 0, TAU);
        }
        ctx.fill();
        ctx.restore();
      }
    }
  }

  drawPulse(game) {
    const pulse = game.pulse;
    if (!pulse || pulse.t >= pulse.maxT) return;
    const ctx = this.ctx;
    const t = pulse.t / pulse.maxT;
    const [sx, sy] = this.screen(pulse.x, pulse.y);
    const r = easeOutCubic(t) * pulse.radius * this.zoom;
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    for (let i = 0; i < 2; i++) {
      const rr = r - i * 26 * this.zoom;
      if (rr <= 0) continue;
      ctx.beginPath();
      ctx.arc(sx, sy, rr, 0, TAU);
      ctx.strokeStyle = rgba('#7dfff1', (1 - t) * (i === 0 ? 0.5 : 0.2));
      ctx.lineWidth = (i === 0 ? 2.5 : 6) * (1 - t * 0.4);
      ctx.stroke();
    }
    const g = ctx.createRadialGradient(sx, sy, r * 0.55, sx, sy, r);
    g.addColorStop(0, 'rgba(90,255,235,0)');
    g.addColorStop(0.85, `rgba(90,255,235,${0.06 * (1 - t)})`);
    g.addColorStop(1, 'rgba(90,255,235,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(sx, sy, r, 0, TAU); ctx.fill();
    ctx.restore();
  }

  drawFrameFronds() {
    const ctx = this.ctx, W = this.W, H = this.H, pal = this.pal;
    const cam = this.camera;
    for (const f of this.frameFronds) {
      const baseX = f.side < 0 ? f.x * W - 40 + (cam.x % 30) * 0.4 : W - f.x * W + 40 - (cam.x % 30) * 0.4;
      const baseY = H + 30 - (cam.y % 20) * 0.2;
      const h = H * f.height;
      ctx.save();
      ctx.translate(baseX, baseY);
      ctx.rotate(f.side * 0.05);
      const sway = Math.sin(this.time * 0.42 + f.phase) * 22 + f.lean * 30;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.bezierCurveTo(-f.side * 14, -h * 0.36, sway * 0.6 - f.side * 14, -h * 0.72, sway, -h);
      ctx.strokeStyle = rgba(mixColor(pal.kelpDark, '#000000', f.dark), 0.88);
      ctx.lineWidth = f.width * 2.4;
      ctx.lineCap = 'round';
      ctx.stroke();
      ctx.strokeStyle = rgba(mixColor(pal.kelp, pal.rim, 0.12), 0.22);
      ctx.lineWidth = f.width * 0.8;
      ctx.stroke();
      for (let l = 0; l < f.leaves; l++) {
        const t = 0.22 + l * 0.14;
        const lx = lerp(0, sway, t) + Math.sin(t * 9 + f.phase) * 8;
        const ly = -h * t;
        const dir = (l % 2 ? 1 : -1) * f.side;
        ctx.save();
        ctx.translate(lx, ly);
        ctx.rotate(dir * 0.9 + Math.sin(this.time * 0.7 + l + f.phase) * 0.16);
        ctx.beginPath();
        ctx.ellipse(dir * 16, 0, 23, 5.5, 0, 0, TAU);
        ctx.fillStyle = rgba(mixColor(pal.kelpDark, '#000', f.dark * 0.7), 0.82);
        ctx.fill();
        ctx.restore();
      }
      ctx.restore();
    }

    // Keep the bottom of the frame grounded.
    const g = ctx.createLinearGradient(0, H * 0.78, 0, H);
    g.addColorStop(0, 'rgba(0,5,10,0)');
    g.addColorStop(1, 'rgba(0,4,8,.52)');
    ctx.fillStyle = g;
    ctx.fillRect(0, H * 0.72, W, H * 0.28);
  }

  drawScreenFx(game) {
    const ctx = this.ctx, W = this.W, H = this.H;
    const player = game.player;
    // Damage vignette.
    if (game.damageFlash > 0) {
      const a = clamp(game.damageFlash, 0, 1);
      const g = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.2, W / 2, H / 2, Math.max(W, H) * 0.72);
      g.addColorStop(0, 'rgba(255,40,30,0)');
      g.addColorStop(0.6, `rgba(220,36,28,${0.12 * a})`);
      g.addColorStop(1, `rgba(180,20,18,${0.5 * a})`);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
    }
    // Low oxygen blue edges.
    const o2 = player.oxygen / player.oxygenMax;
    if (o2 < 0.3 && game.mode === 'playing') {
      const a = (1 - o2 / 0.3) * (0.55 + 0.45 * Math.sin(game.time * 3.6));
      const g = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.28, W / 2, H / 2, Math.max(W, H) * 0.75);
      g.addColorStop(0, 'rgba(10,40,80,0)');
      g.addColorStop(0.7, `rgba(4,36,74,${0.12 * a})`);
      g.addColorStop(1, `rgba(2,14,34,${0.48 * a})`);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
    }
    // Pressure edges.
    if (game.pressureOver) {
      const a = 0.28 + 0.18 * Math.sin(game.time * 5);
      const g = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.25, W / 2, H / 2, Math.max(W, H) * 0.7);
      g.addColorStop(0, 'rgba(255,120,60,0)');
      g.addColorStop(1, `rgba(160,40,20,${a})`);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
    }

    // Lantern halo around the submarine in the dark.
    if (game.mode === 'playing' || game.mode === 'title') {
      const [sx, sy] = this.screen(player.x, player.y);
      const rad = (140 + (player.lightsOn ? 80 : 0)) * this.zoom;
      const glow = ctx.createRadialGradient(sx, sy, 0, sx, sy, rad);
      const strength = clamp((game.camera.y - 1200) / 2600, 0, 0.5) + 0.04;
      glow.addColorStop(0, `rgba(180,250,245,${strength})`);
      glow.addColorStop(0.45, `rgba(110,210,220,${strength * 0.32})`);
      glow.addColorStop(1, 'rgba(2,20,30,0)');
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      ctx.fillStyle = glow;
      ctx.fillRect(sx - rad, sy - rad, rad * 2, rad * 2);
      ctx.restore();
    }

    // Classic lens vignette.
    const v = ctx.createRadialGradient(W * 0.5, H * 0.46, Math.min(W, H) * 0.32, W * 0.5, H * 0.46, Math.max(W, H) * 0.78);
    v.addColorStop(0, 'rgba(0,6,12,0)');
    v.addColorStop(0.76, 'rgba(0,5,10,.16)');
    v.addColorStop(1, 'rgba(0,3,7,.62)');
    ctx.fillStyle = v;
    ctx.fillRect(0, 0, W, H);
  }
}

/* Hand-drawn reef life, wreckage and collectibles. */
import { TAU, clamp, rgba, mixColor, lerp } from './utils.js';
import { drawRuin } from './render-ruins.js';

export { drawRuin };

function localGlow(ctx, x, y, radius, color, alpha = 0.5) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, radius);
  g.addColorStop(0, rgba(color, alpha));
  g.addColorStop(0.42, rgba(color, alpha * 0.34));
  g.addColorStop(1, rgba(color, 0));
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(x, y, radius, 0, TAU); ctx.fill();
}

function localKelp(r, ctx, height, count, spread, phase, time, colorA, colorB, lean = 0, fg = false) {
  for (let i = 0; i < count; i++) {
    const bx = (i - (count - 1) / 2) * spread;
    const h = height * (0.68 + 0.32 * Math.abs(Math.sin(phase + i * 1.71)));
    const swayA = Math.sin(time * 0.55 + phase + i * 0.8) * (14 + h * 0.08);
    const swayB = Math.sin(time * 0.43 + phase * 1.7 + i * 1.3) * (20 + h * 0.1);
    ctx.beginPath();
    ctx.moveTo(bx, 6);
    ctx.bezierCurveTo(bx + swayA * 0.35 + lean * 20, -h * 0.33, bx + swayB * 0.6 + lean * 45, -h * 0.72, bx + swayB + lean * 55, -h);
    ctx.strokeStyle = rgba(colorA, fg ? 0.92 : 0.78);
    ctx.lineWidth = (2.6 + (i % 3) * 0.7) * (fg ? 1.2 : 1);
    ctx.lineCap = 'round';
    ctx.stroke();
    ctx.strokeStyle = rgba(colorB, fg ? 0.2 : 0.42);
    ctx.lineWidth = 1.1;
    ctx.stroke();

    const leaves = fg ? 2 : 4;
    for (let l = 0; l < leaves; l++) {
      const t = 0.26 + l * 0.17;
      const lx = bx + swayB * t * t + Math.sin(time * 0.8 + l + phase + i) * 4;
      const ly = -h * t;
      const dir = (l % 2 === 0 ? 1 : -1);
      ctx.save();
      ctx.translate(lx, ly);
      ctx.rotate(dir * 1.05 + Math.sin(time * 0.7 + l + phase) * 0.2);
      ctx.beginPath();
      ctx.ellipse(dir * 9, 0, 13 - l * 1.1, 3.1, 0, 0, TAU);
      ctx.fillStyle = rgba(l % 2 ? colorB : colorA, fg ? 0.8 : 0.55);
      ctx.fill();
      ctx.restore();
    }
  }
}

/* ------------------------------------------------------------------ */
export function drawReef(r, obj, p = 1, fg = false) {
  const ctx = r.ctx;
  const [sx, sy] = r.screen(obj.x, obj.y, p);
  const scale = r.zoom * obj.scale * (fg ? 1.08 : 1);
  if (sx < -420 || sx > r.W + 420 || sy < -420 || sy > r.H + 460) return;
  const pal = r.palFor(obj.zone);

  ctx.save();
  ctx.translate(sx, sy);
  ctx.scale(scale, scale);

  // Cool shadow cast into the water.
  const shadow = ctx.createRadialGradient(0, 26, 10, 0, 26, 190);
  shadow.addColorStop(0, 'rgba(0,4,9,.3)');
  shadow.addColorStop(1, 'rgba(0,4,9,0)');
  ctx.fillStyle = shadow;
  ctx.beginPath(); ctx.ellipse(0, 30, 190, 70, 0, 0, TAU); ctx.fill();

  // Rock lumps, back to front.
  for (let i = 0; i < obj.lumps.length; i++) {
    const l = obj.lumps[i];
    ctx.save();
    ctx.translate(l.dx, l.dy);
    ctx.rotate(l.rot);
    const top = mixColor(pal.rockTop, pal.rim, 0.08 + l.tone * 0.11);
    const bottom = mixColor(pal.rockBottom, '#000000', 0.14 + (1 - l.tone) * 0.2);
    const g = ctx.createLinearGradient(0, -l.ry, 0, l.ry);
    g.addColorStop(0, top);
    g.addColorStop(0.46, mixColor(pal.rockTop, pal.rockBottom, 0.55));
    g.addColorStop(1, bottom);
    r.blobPath(0, 0, l.rx, l.ry, obj.seed + i * 13.7, 14, 0.18);
    ctx.fillStyle = g;
    ctx.fill();
    ctx.strokeStyle = rgba(pal.rim, fg ? 0.05 : 0.1);
    ctx.lineWidth = 1.2;
    ctx.stroke();

    // Weathering, crevices and a lit upper edge.
    ctx.save();
    r.blobPath(0, 0, l.rx, l.ry, obj.seed + i * 13.7, 14, 0.18);
    ctx.clip();
    ctx.strokeStyle = 'rgba(0,8,12,.25)';
    ctx.lineWidth = 1.2;
    for (let c = 0; c < 3; c++) {
      const cx = Math.sin(obj.seed + c * 4.1 + i) * l.rx * 0.6;
      ctx.beginPath();
      ctx.moveTo(cx, -l.ry * 0.7);
      ctx.quadraticCurveTo(cx + l.rx * 0.24, 0, cx - l.rx * 0.12, l.ry * 0.75);
      ctx.stroke();
    }
    ctx.strokeStyle = rgba(pal.rim, 0.11);
    ctx.lineWidth = 2.2;
    ctx.beginPath();
    ctx.ellipse(-l.rx * 0.08, -l.ry * 0.42, l.rx * 0.76, l.ry * 0.55, -0.12, Math.PI * 1.06, Math.PI * 1.92);
    ctx.stroke();
    ctx.restore();
    ctx.restore();
  }

  // Moss and encrusting life.
  ctx.save();
  ctx.globalAlpha = fg ? 0.2 : 0.32;
  ctx.fillStyle = pal.kelp;
  r.blobPath(-30, 12, 96, 20, obj.seed + 2, 9, 0.3);
  ctx.fill();
  ctx.fillStyle = pal.coral[obj.seed % pal.coral.length];
  r.blobPath(62, 2, 36, 10, obj.seed + 8, 8, 0.28);
  ctx.fill();
  ctx.restore();

  // Living foliage.
  for (const plant of obj.plants) {
    const color = mixColor(pal.coral[plant.hue % pal.coral.length], pal.rim, 0.08);
    ctx.save();
    ctx.translate(plant.dx, plant.dy);
    if (plant.kind === 'kelp' || plant.kind === 'whip') {
      const h = (plant.kind === 'whip' ? 70 : 120) * plant.size;
      localKelp(r, ctx, h, 3 + Math.round(plant.size * 2), 13 * plant.size, plant.phase, r.time,
        mixColor(pal.kelp, '#000', 0.14), plant.kind === 'whip' ? color : pal.kelp, plant.lean, fg);
    } else if (plant.kind === 'fan') {
      drawFanLocal(ctx, color, plant.size, plant.phase, r.time, fg);
    } else if (plant.kind === 'branch') {
      drawBranchLocal(ctx, color, plant.size, plant.phase, r.time, fg);
    } else if (plant.kind === 'tube') {
      drawTubeLocal(ctx, color, plant.size, plant.phase, r.time, pal, fg, obj.zone);
    } else {
      drawAnemoneLocal(ctx, color, plant.size, plant.phase, r.time, fg);
    }
    ctx.restore();
  }

  // Cold bioluminescence on deep reefs.
  if (obj.zone === 'midnight' || obj.zone === 'abyss') {
    for (let i = 0; i < 7; i++) {
      const a = obj.seed + i * 2.3;
      const x = Math.sin(a) * 100;
      const y = Math.cos(a * 1.4) * 28 - 8;
      const pulse = 0.3 + 0.7 * (0.5 + 0.5 * Math.sin(r.time * 1.2 + a));
      localGlow(ctx, x, y, 12, pal.accent, 0.22 * pulse);
      ctx.fillStyle = rgba(pal.accent, 0.55 * pulse);
      ctx.beginPath(); ctx.arc(x, y, 1.6, 0, TAU); ctx.fill();
    }
  }
  ctx.restore();
}

export function drawKelp(r, obj, p = 1, fg = false) {
  const ctx = r.ctx;
  const [sx, sy] = r.screen(obj.x, obj.y, p);
  if (sx < -260 || sx > r.W + 260 || sy < -400 || sy > r.H + 260) return;
  const pal = r.palFor(obj.zone);
  const scale = r.zoom * obj.scale * (fg ? 1.1 : 1);
  ctx.save();
  ctx.translate(sx, sy);
  ctx.scale(scale, scale);
  ctx.fillStyle = rgba(mixColor(pal.rockBottom, '#000', 0.35), 0.9);
  ctx.beginPath(); ctx.ellipse(0, 8, obj.spread * 1.4, 11, 0, 0, TAU); ctx.fill();
  localKelp(r, ctx, obj.height, obj.count, obj.spread, obj.phase, r.time,
    fg ? mixColor(pal.kelpDark, '#000', 0.45) : mixColor(pal.kelp, '#000', 0.24),
    fg ? 'rgba(80,160,140,1)' : mixColor(pal.kelp, pal.rim, 0.15), 0, fg);
  ctx.restore();
}

export function drawCoral(r, obj, p = 1) {
  const ctx = r.ctx;
  const [sx, sy] = r.screen(obj.x, obj.y, p);
  if (sx < -180 || sx > r.W + 180 || sy < -220 || sy > r.H + 180) return;
  const pal = r.palFor(obj.zone);
  const scale = r.zoom * obj.scale * 0.92;
  const color = mixColor(pal.coral[obj.hue % pal.coral.length], pal.rim, 0.06);
  ctx.save();
  ctx.translate(sx, sy);
  ctx.scale(scale, scale);
  ctx.fillStyle = rgba(pal.rockBottom, 0.55);
  ctx.beginPath(); ctx.ellipse(0, 4, 24, 6, 0, 0, TAU); ctx.fill();
  if (obj.style === 'fan') drawFanLocal(ctx, color, 1.1, obj.phase, r.time, false);
  else if (obj.style === 'branch') drawBranchLocal(ctx, color, 1.05, obj.phase, r.time, false);
  else if (obj.style === 'tube') drawTubeLocal(ctx, color, 1, obj.phase, r.time, pal, false, obj.zone);
  else drawBrainLocal(ctx, color, obj.phase, r.time);
  ctx.restore();
}

function drawFanLocal(ctx, color, size, phase, time, fg) {
  ctx.save();
  ctx.scale(size, size);
  const sway = Math.sin(time * 0.5 + phase) * 0.02;
  ctx.rotate(sway);
  ctx.strokeStyle = rgba(color, fg ? 0.45 : 0.78);
  ctx.lineCap = 'round';
  ctx.strokeStyle = rgba(color, fg ? 0.5 : 0.82);
  for (let i = 0; i < 9; i++) {
    const a = -Math.PI * 0.8 + (i / 8) * Math.PI * 0.6;
    const len = 45 + (i % 3) * 12;
    ctx.lineWidth = 2.1 - (i % 3) * 0.3;
    ctx.beginPath();
    ctx.moveTo(0, 4);
    ctx.quadraticCurveTo(Math.cos(a) * len * 0.6, Math.sin(a) * len * 0.55, Math.cos(a) * len, Math.sin(a) * len - 6);
    ctx.stroke();
    // fan lattice
    for (let j = 1; j < 3; j++) {
      const t = j / 3;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * len * t * 0.74, Math.sin(a) * len * t * 0.8);
      ctx.lineTo(Math.cos(a + 0.16) * len * t * 0.9, Math.sin(a + 0.16) * len * t * 0.9);
      ctx.strokeStyle = rgba(color, 0.35);
      ctx.lineWidth = 0.8;
      ctx.stroke();
    }
  }
  ctx.strokeStyle = rgba(color, 0.9);
  ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(0, 5); ctx.lineTo(0, -8); ctx.stroke();
  ctx.restore();
}

function drawBranchLocal(ctx, color, size, phase, time, fg) {
  ctx.save();
  ctx.scale(size, size);
  ctx.rotate(Math.sin(time * 0.45 + phase) * 0.015);
  const branch = (x, y, angle, len, width, depth) => {
    const nx = x + Math.cos(angle) * len;
    const ny = y + Math.sin(angle) * len;
    ctx.strokeStyle = rgba(depth > 1 ? mixColor(color, '#ffffff', 0.08) : mixColor(color, '#061820', 0.12), fg ? 0.6 : 0.88);
    ctx.lineWidth = width;
    ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(x, y); ctx.quadraticCurveTo((x + nx) / 2 + Math.sin(phase + depth) * 5, (y + ny) / 2, nx, ny); ctx.stroke();
    if (depth > 0) {
      branch(nx, ny, angle - 0.44 - (depth % 2) * 0.12, len * 0.7, width * 0.65, depth - 1);
      branch(nx, ny, angle + 0.5, len * 0.66, width * 0.6, depth - 1);
    } else {
      ctx.fillStyle = rgba(color, 0.8);
      ctx.beginPath(); ctx.arc(nx, ny, 2.4, 0, TAU); ctx.fill();
    }
  };
  branch(0, 4, -Math.PI / 2, 24, 4.2, 3);
  branch(0, 4, -Math.PI / 2 - 0.45, 17, 3, 2);
  branch(0, 4, -Math.PI / 2 + 0.4, 18, 3, 2);
  ctx.restore();
}

function drawTubeLocal(ctx, color, size, phase, time, pal, fg, zoneId) {
  ctx.save();
  ctx.scale(size, size);
  const deep = zoneId === 'midnight' || zoneId === 'abyss';
  for (let i = 0; i < 5; i++) {
    const x = (i - 2) * 9;
    const h = 25 + ((i * 13) % 22) + Math.sin(time * 0.6 + phase + i) * 1.5;
    const grad = ctx.createLinearGradient(x, -h, x, 2);
    grad.addColorStop(0, rgba(mixColor(color, '#ffffff', 0.2), fg ? 0.5 : 0.9));
    grad.addColorStop(1, rgba(mixColor(color, '#061820', 0.3), 0.85));
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(x - 4, 2);
    ctx.quadraticCurveTo(x - 5, -h * 0.6, x - 4.5, -h);
    ctx.lineTo(x + 4.5, -h);
    ctx.quadraticCurveTo(x + 5, -h * 0.6, x + 4, 2);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = deep ? rgba(pal.accent, 0.8) : rgba(mixColor(color, '#fff', 0.45), 0.9);
    ctx.beginPath(); ctx.ellipse(x, -h + 1, 4.1, 1.8, 0, 0, TAU); ctx.fill();
    if (deep) localGlow(ctx, x, -h, 13, pal.accent, 0.28);
  }
  ctx.restore();
}

function drawAnemoneLocal(ctx, color, size, phase, time, fg) {
  ctx.save();
  ctx.scale(size, size);
  ctx.fillStyle = rgba(mixColor(color, '#061820', 0.2), 0.8);
  ctx.beginPath(); ctx.ellipse(0, 2, 18, 8, 0, 0, TAU); ctx.fill();
  for (let i = 0; i < 10; i++) {
    const a = -Math.PI * 0.92 + (i / 9) * Math.PI * 0.84;
    const len = 17 + Math.sin(i * 2.1) * 5;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(Math.cos(a) * len * 0.6, Math.sin(a) * len * 0.6, Math.cos(a) * len + Math.sin(time + phase + i) * 2.3, Math.sin(a) * len);
    ctx.strokeStyle = rgba(mixColor(color, '#fff', 0.16), fg ? 0.5 : 0.8);
    ctx.lineWidth = 1.5;
    ctx.lineCap = 'round';
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(Math.cos(a) * len, Math.sin(a) * len, 1.6, 0, TAU);
    ctx.fillStyle = rgba(mixColor(color, '#fff', 0.55), 0.9);
    ctx.fill();
  }
  ctx.restore();
}

function drawBrainLocal(ctx, color, phase, time) {
  ctx.save();
  const grad = ctx.createRadialGradient(-8, -12, 2, 0, 0, 32);
  grad.addColorStop(0, rgba(mixColor(color, '#fff', 0.2), 0.9));
  grad.addColorStop(1, rgba(mixColor(color, '#04111b', 0.3), 0.9));
  ctx.fillStyle = grad;
  rBlob(ctx, 0, -8, 30, 22);
  ctx.fill();
  ctx.strokeStyle = rgba(mixColor(color, '#04111b', 0.5), 0.55);
  ctx.lineWidth = 1.3;
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.arc(-12 + i * 8, -10 + Math.sin(i + phase) * 3, 8, 0.3, Math.PI * 1.2);
    ctx.stroke();
  }
  ctx.restore();
}

function rBlob(ctx, x, y, rx, ry) {
  ctx.beginPath();
  for (let i = 0; i < 12; i++) {
    const a = i / 12 * TAU;
    const n = 1 + Math.sin(i * 2.7) * 0.08;
    const px = x + Math.cos(a) * rx * n, py = y + Math.sin(a) * ry * n;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath();
}

/* ------------------------------------------------------------------ */
export function drawVent(r, obj, p = 1) {
  const ctx = r.ctx;
  const [sx, sy] = r.screen(obj.x, obj.y, p);
  if (sx < -220 || sx > r.W + 220 || sy < -300 || sy > r.H + 200) return;
  const pal = r.palFor(obj.zone);
  const scale = r.zoom * obj.scale;
  const hot = obj.zone === 'abyss' ? mixColor('#ff965c', pal.accent, 0.28) : '#ff9457';
  ctx.save();
  ctx.translate(sx, sy);
  ctx.scale(scale, scale);

  // Chimney stack.
  const g = ctx.createLinearGradient(-24, 0, 30, 0);
  g.addColorStop(0, '#061018');
  g.addColorStop(0.4, mixColor(pal.rockTop, '#000', 0.2));
  g.addColorStop(1, '#02080c');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-38, 44);
  ctx.lineTo(-22, -64);
  ctx.lineTo(-10, -78);
  ctx.lineTo(4, -72);
  ctx.lineTo(11, -48);
  ctx.lineTo(25, 44);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = rgba(pal.rim, 0.09);
  ctx.lineWidth = 1.2;
  ctx.stroke();
  // Strata.
  ctx.strokeStyle = 'rgba(0,4,8,.32)';
  ctx.lineWidth = 2;
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(-30 + i * 2, -46 + i * 20);
    ctx.lineTo(14 + i, -40 + i * 19);
    ctx.stroke();
  }
  // Vent mouth.
  ctx.beginPath(); ctx.ellipse(-4, -75, 12, 5, -0.1, 0, TAU);
  ctx.fillStyle = '#180a05'; ctx.fill();
  localGlow(ctx, -3, -76, 42 + Math.sin(r.time * 1.7 + obj.seed) * 6, hot, 0.5);
  ctx.beginPath(); ctx.ellipse(-3, -76, 8, 2.4, 0, 0, TAU);
  ctx.fillStyle = rgba('#ffbf7a', 0.85); ctx.fill();

  // Rising black smoke / shimmer.
  for (let i = 0; i < 6; i++) {
    const t = (r.time * 0.16 + i / 6 + obj.seed * 0.001) % 1;
    const yy = -86 - t * 130;
    const xx = -3 + Math.sin(t * 7 + obj.seed + i) * (8 + t * 22);
    const rr = 5 + t * 19;
    ctx.globalAlpha = (1 - t) * 0.22;
    ctx.fillStyle = i % 3 === 0 ? hot : '#07131c';
    ctx.beginPath(); ctx.ellipse(xx, yy, rr * 1.3, rr, 0.2, 0, TAU); ctx.fill();
  }
  ctx.globalAlpha = 1;
  ctx.restore();
}

/* ------------------------------------------------------------------ */
export function drawBeacon(r, obj, p = 1) {
  const ctx = r.ctx;
  const [sx, sy] = r.screen(obj.x, obj.y, p);
  if (!r.visible(obj.x, obj.y, 200, p)) return;
  const bob = Math.sin(r.time * 1.2 + 1.5) * 3;
  ctx.save();
  ctx.translate(sx, sy + bob);
  ctx.scale(r.zoom, r.zoom);
  r.drawGlow(0, 0, '#7dffe9', 60, 0.3);
  ctx.strokeStyle = 'rgba(141,244,234,.4)';
  ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.moveTo(-26, -22); ctx.lineTo(26, -22); ctx.stroke();
  ctx.fillStyle = '#0a2c3a';
  r.roundRect(-16, -18, 32, 34, 5); ctx.fill();
  ctx.strokeStyle = 'rgba(151,246,238,.55)'; ctx.stroke();
  ctx.fillStyle = '#5cf1de';
  ctx.beginPath(); ctx.arc(0, 2, 5, 0, TAU); ctx.fill();
  localGlow(ctx, 0, 2, 28, '#7dffe9', 0.5);
  ctx.strokeStyle = 'rgba(132,246,236,.3)';
  ctx.beginPath(); ctx.moveTo(0, -22); ctx.lineTo(0, -45); ctx.stroke();
  ctx.fillStyle = '#ffcf7a';
  ctx.beginPath(); ctx.arc(0, -46, 2.5, 0, TAU); ctx.fill();
  ctx.restore();
}

/* ------------------------------------------------------------------ */
export function drawChest(r, chest, game) {
  const ctx = r.ctx;
  const [rawX, rawY] = r.screen(chest.x, chest.y);
  const bob = Math.sin(game.time * 1.5 + chest.x * 0.01) * 3;
  const sx = rawX, sy = rawY + bob;
  if (sx < -120 || sx > r.W + 120 || sy < -150 || sy > r.H + 120) return;
  const tier = chest.tier || 1;
  const gold = tier >= 5 ? '#c7a2ff' : tier >= 4 ? '#9ff5e3' : '#ffd36f';
  const opened = chest.opened;

  r.drawGlow(sx, sy - 4, gold, 62 + tier * 6, opened ? 0.18 : 0.42);
  if (!opened) {
    for (let i = 0; i < 4; i++) {
      const a = game.time * 0.8 + i * 1.7 + chest.x;
      const px = sx + Math.cos(a) * (27 + i * 4);
      const py = sy - 8 + Math.sin(a * 1.3) * (13 + i * 2);
      ctx.fillStyle = rgba(gold, 0.42 + 0.28 * Math.sin(game.time * 2 + i));
      ctx.beginPath(); ctx.arc(px, py, 1.2 + (i % 2) * 0.7, 0, TAU); ctx.fill();
    }
  }

  // Sonar beam.
  if (!opened && chest.pingUntil > game.time) {
    const a = clamp((chest.pingUntil - game.time) / 6, 0, 1);
    const grad = ctx.createLinearGradient(sx, sy - 280, sx, sy);
    grad.addColorStop(0, rgba(gold, 0));
    grad.addColorStop(1, rgba(gold, 0.22 * a));
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(sx - 15, sy); ctx.lineTo(sx + 15, sy); ctx.lineTo(sx + 35, sy - 300); ctx.lineTo(sx - 35, sy - 300); ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = rgba(gold, 0.3 * a);
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(sx, sy - 4, 24 + Math.sin(game.time * 3) * 4, 0, TAU); ctx.stroke();
  }

  ctx.save();
  ctx.translate(sx, sy);
  ctx.scale(r.zoom, r.zoom);

  // Ledge.
  ctx.fillStyle = 'rgba(0,5,9,.42)';
  ctx.beginPath(); ctx.ellipse(0, 19, 44, 10, 0, 0, TAU); ctx.fill();
  ctx.fillStyle = mixColor(r.pal.rockTop, '#000', 0.15);
  r.blobPath(0, 15, 38, 10, chest.x, 10, 0.2);
  ctx.fill();

  // Chest box.
  const wood = ctx.createLinearGradient(0, -18, 0, 18);
  wood.addColorStop(0, tier >= 5 ? '#3b2a58' : '#3d2b1d');
  wood.addColorStop(0.55, tier >= 5 ? '#1e1530' : '#251a13');
  wood.addColorStop(1, '#0c0a0b');
  ctx.fillStyle = wood;
  r.roundRect(-28, -10, 56, 28, 4);
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,.55)';
  ctx.lineWidth = 1.2;
  ctx.stroke();
  // Planks.
  ctx.strokeStyle = 'rgba(255,210,140,.09)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath(); ctx.moveTo(-24 + i * 14, -8); ctx.lineTo(-24 + i * 14, 16); ctx.stroke();
  }
  // Bands.
  ctx.fillStyle = rgba(gold, 0.72);
  ctx.fillRect(-31, -2, 62, 3.2);
  ctx.fillRect(-31, 10, 62, 2.4);
  // Lid.
  const lidY = opened ? -24 : -14;
  ctx.save();
  if (opened) {
    ctx.translate(-28, -10);
    ctx.rotate(-0.68);
    ctx.translate(28, 10);
  }
  const lid = ctx.createLinearGradient(0, -20, 0, 2);
  lid.addColorStop(0, tier >= 5 ? '#4a356b' : '#4b3421');
  lid.addColorStop(1, '#1a110c');
  ctx.fillStyle = lid;
  r.roundRect(-30, -22, 60, 18, 7);
  ctx.fill();
  ctx.strokeStyle = rgba(gold, 0.62);
  ctx.lineWidth = 1.8;
  ctx.stroke();
  ctx.fillStyle = rgba(gold, 0.55);
  ctx.fillRect(-32, -12, 64, 2);
  ctx.restore();
  // Lock.
  if (!opened) {
    ctx.fillStyle = rgba(gold, 0.9);
    r.roundRect(-5, -4, 10, 10, 2);
    ctx.fill();
    ctx.fillStyle = '#2a1b0d';
    ctx.beginPath(); ctx.arc(0, 1, 1.8, 0, TAU); ctx.fill();
  } else {
    // Glowing interior.
    const inner = ctx.createRadialGradient(0, -8, 0, 0, -8, 34);
    inner.addColorStop(0, rgba(gold, 0.85));
    inner.addColorStop(0.5, rgba(gold, 0.2));
    inner.addColorStop(1, rgba(gold, 0));
    ctx.fillStyle = inner;
    ctx.beginPath(); ctx.ellipse(0, -8, 34, 20, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = '#ffe9ae';
    for (let i = 0; i < 5; i++) {
      const a = game.time * 1.4 + i * 1.9;
      ctx.beginPath(); ctx.arc(Math.cos(a) * 14, -8 + Math.sin(a * 1.3) * 6, 1.4, 0, TAU); ctx.fill();
    }
  }
  // Tier gems on the front.
  if (tier >= 4) {
    ctx.fillStyle = rgba(gold, 0.9);
    ctx.beginPath();
    ctx.moveTo(0, 3); ctx.lineTo(4, 7); ctx.lineTo(0, 11); ctx.lineTo(-4, 7); ctx.closePath();
    ctx.fill();
  }
  ctx.restore();
}

/* ------------------------------------------------------------------ */
export function drawResource(r, res, game) {
  const ctx = r.ctx;
  const bob = Math.sin(game.time * 2 + res.phase) * 4;
  const [sx, sy] = r.screen(res.x, res.y + bob);
  if (sx < -60 || sx > r.W + 60 || sy < -60 || sy > r.H + 60) return;
  const colors = {
    scrap: '#ffc46d', pearl: '#f5ecff', crystal: '#7ff7ee', oxygen: '#72e9ff', repair: '#9cf7a8',
  };
  const color = colors[res.type] || '#ffd36f';
  const scale = r.zoom;
  const pulse = 0.85 + 0.15 * Math.sin(game.time * 2.4 + res.phase);
  r.drawGlow(sx, sy, color, 34 * pulse, 0.34);
  if (res.pingUntil > game.time) {
    ctx.save();
    ctx.strokeStyle = rgba(color, 0.5);
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(sx, sy, 22 + Math.sin(game.time * 3 + res.phase) * 3, 0, TAU); ctx.stroke();
    ctx.restore();
  }
  ctx.save();
  ctx.translate(sx, sy);
  ctx.rotate(Math.sin(game.time * 1.15 + res.phase) * 0.1);
  ctx.scale(scale, scale);

  if (res.type === 'scrap') {
    // A small cluster of recovered machinery.
    ctx.strokeStyle = 'rgba(43,21,7,.55)';
    ctx.fillStyle = 'rgba(255,188,84,.92)';
    ctx.lineWidth = 2;
    gear(ctx, -4, 2, 8.5, 8, game.time * 0.4 + res.phase);
    gear(ctx, 9, -6, 5.2, 6, -game.time * 0.55);
    ctx.fillStyle = 'rgba(255,231,169,.9)';
    ctx.beginPath(); ctx.arc(-4, 2, 2.6, 0, TAU); ctx.fill();
  } else if (res.type === 'pearl') {
    ctx.fillStyle = 'rgba(158,108,150,.7)';
    ctx.beginPath(); ctx.ellipse(0, 5, 15, 9, 0, 0, Math.PI); ctx.fill();
    ctx.strokeStyle = 'rgba(255,220,244,.55)'; ctx.lineWidth = 1; ctx.stroke();
    const pg = ctx.createRadialGradient(-3, -4, 1, 0, -3, 10);
    pg.addColorStop(0, '#ffffff');
    pg.addColorStop(0.54, '#fff2ff');
    pg.addColorStop(1, '#bca1d8');
    ctx.fillStyle = pg;
    ctx.beginPath(); ctx.arc(0, -3, 8.5, 0, TAU); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.8)';
    ctx.beginPath(); ctx.arc(-3, -6, 2, 0, TAU); ctx.fill();
  } else if (res.type === 'crystal') {
    const shards = [[-8, 10, -2, -14], [1, 13, 7, -17], [10, 12, 12, -7]];
    for (let i = 0; i < shards.length; i++) {
      const [x1, y1, x2, y2] = shards[i];
      const g = ctx.createLinearGradient(x1, y1, x2, y2);
      const zc = r.palFor(res.zone).accent;
      g.addColorStop(0, rgba(mixColor(zc, '#ffffff', 0.4), 0.58));
      g.addColorStop(0.5, rgba(zc, 0.86));
      g.addColorStop(1, rgba(mixColor(zc, '#001018', 0.25), 0.95));
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.moveTo(x1, y1); ctx.lineTo(x1 - 3, y1 - 3); ctx.lineTo(x2, y2); ctx.lineTo(x2 + 4, y2 + 3); ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = rgba('#ffffff', 0.35); ctx.lineWidth = 0.7; ctx.stroke();
    }
  } else if (res.type === 'oxygen') {
    const orb = ctx.createRadialGradient(-4, -6, 1, 0, 0, 16);
    orb.addColorStop(0, 'rgba(235,255,255,.92)');
    orb.addColorStop(0.44, 'rgba(113,238,255,.4)');
    orb.addColorStop(1, 'rgba(20,114,146,.18)');
    ctx.fillStyle = orb;
    ctx.beginPath(); ctx.arc(0, 0, 14, 0, TAU); ctx.fill();
    ctx.strokeStyle = 'rgba(178,251,255,.68)'; ctx.lineWidth = 1.2; ctx.stroke();
    ctx.fillStyle = 'rgba(255,255,255,.75)';
    ctx.beginPath(); ctx.arc(-4, -5, 2.2, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(7, 6, 1.3, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(-7, 7, 1, 0, TAU); ctx.fill();
  } else {
    // Repair kit.
    ctx.rotate(-0.06);
    const g = ctx.createLinearGradient(0, -12, 0, 13);
    g.addColorStop(0, '#d9fff0');
    g.addColorStop(0.3, '#6fdca8');
    g.addColorStop(1, '#1b7660');
    ctx.fillStyle = g;
    r.roundRect(-13, -10, 26, 21, 4); ctx.fill();
    ctx.strokeStyle = 'rgba(3,36,35,.5)'; ctx.lineWidth = 1.2; ctx.stroke();
    ctx.fillStyle = 'rgba(4,46,42,.85)';
    ctx.fillRect(-4, -4, 8, 13);
    ctx.fillRect(-8, 0, 16, 5);
    ctx.strokeStyle = 'rgba(220,255,242,.55)';
    ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(-13, -2); ctx.lineTo(13, -2); ctx.stroke();
  }
  ctx.restore();
}

function gear(ctx, x, y, r1, teeth, phase) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(phase);
  ctx.beginPath();
  for (let i = 0; i < teeth * 2; i++) {
    const a = i / (teeth * 2) * TAU;
    const rr = i % 2 === 0 ? r1 : r1 * 0.74;
    const px = Math.cos(a) * rr, py = Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.beginPath(); ctx.arc(0, 0, r1 * 0.32, 0, TAU);
  ctx.globalCompositeOperation = 'destination-out';
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';
  ctx.restore();
}

/* Wrecks, ruins, temples and other large hand-placed landmarks. */
import { TAU, rgba, mixColor, clamp } from './utils.js';

function localGlow(ctx, x, y, radius, color, alpha = 0.5) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, radius);
  g.addColorStop(0, rgba(color, alpha));
  g.addColorStop(0.45, rgba(color, alpha * 0.32));
  g.addColorStop(1, rgba(color, 0));
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(x, y, radius, 0, TAU); ctx.fill();
}

function stoneGrad(ctx, pal, x0, y0, x1, y1, lit = 0.08) {
  const g = ctx.createLinearGradient(x0, y0, x1, y1);
  g.addColorStop(0, mixColor(pal.rockTop, pal.rim, lit));
  g.addColorStop(0.44, mixColor(pal.rockTop, pal.rockBottom, 0.52));
  g.addColorStop(1, mixColor(pal.rockBottom, '#000', 0.18));
  return g;
}

function block(ctx, pal, x, y, w, h, lit = 0.08, r = 2) {
  ctx.fillStyle = stoneGrad(ctx, pal, x, y, x, y + h, lit);
  ctx.beginPath();
  const rr = Math.min(r, w / 2, h / 2);
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,6,10,.32)';
  ctx.lineWidth = 0.8;
  ctx.stroke();
  // lit top edge
  ctx.strokeStyle = rgba(pal.rim, 0.12);
  ctx.beginPath(); ctx.moveTo(x + 2, y + 0.7); ctx.lineTo(x + w - 2, y + 0.7); ctx.stroke();
}

function crack(ctx, x, y, len, seed) {
  ctx.strokeStyle = 'rgba(0,5,8,.35)';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.moveTo(x, y);
  for (let i = 1; i <= 4; i++) {
    ctx.lineTo(x + Math.sin(seed + i * 1.9) * 4 + i * len * 0.18, y + i * len * 0.24);
  }
  ctx.stroke();
}

export function drawRuin(r, obj, p = 1) {
  const ctx = r.ctx;
  const [sx, sy] = r.screen(obj.x, obj.y, p);
  if (!r.visible(obj.x, obj.y, 720, p)) return;
  const pal = r.palFor(obj.zone);
  const scale = r.zoom * obj.scale;
  ctx.save();
  ctx.translate(sx, sy);
  ctx.scale(scale, scale);
  switch (obj.variant) {
    case 'wreck': drawWreck(r, obj, pal); break;
    case 'temple': drawTemple(r, obj, pal); break;
    case 'vault': drawVault(r, obj, pal); break;
    case 'bones': drawBones(r, obj, pal); break;
    case 'archive': drawArchive(r, obj, pal); break;
    case 'arch': drawArch(r, obj, pal); break;
    case 'slab': drawSlab(r, obj, pal); break;
    default: drawColumns(r, obj, pal); break;
  }
  ctx.restore();
}

/* ------------------------------------------------------------------ */
function drawColumns(r, obj, pal) {
  const ctx = r.ctx;
  // platform
  block(ctx, pal, -104, 28, 208, 25, 0.05, 3);
  block(ctx, pal, -118, 48, 236, 16, 0.03, 2);
  for (let i = 0; i < 3; i++) {
    ctx.strokeStyle = 'rgba(0,5,8,.2)';
    ctx.beginPath(); ctx.moveTo(-100 + i * 70, 30); ctx.lineTo(-100 + i * 70, 52); ctx.stroke();
  }
  // columns
  const cols = [
    { x: -63, h: 132, w: 25, break: 0.72, crack: 1.2 },
    { x: -9, h: 178, w: 28, break: 0.93, crack: 2.8 },
    { x: 55, h: 112, w: 23, break: 0.52, crack: 4.1 },
  ];
  for (let c = 0; c < cols.length; c++) {
    const col = cols[c];
    const baseTop = 28;
    const top = baseTop - col.h * col.break;
    // base
    block(ctx, pal, col.x - col.w / 2 - 5, baseTop - 8, col.w + 10, 11, 0.04, 1);
    // shaft
    ctx.save();
    ctx.translate(col.x, 0);
    const g = ctx.createLinearGradient(-col.w / 2, 0, col.w / 2, 0);
    g.addColorStop(0, mixColor(pal.rockBottom, '#000', 0.12));
    g.addColorStop(0.36, mixColor(pal.rockTop, pal.rim, 0.08));
    g.addColorStop(0.7, mixColor(pal.rockTop, pal.rockBottom, 0.5));
    g.addColorStop(1, mixColor(pal.rockBottom, '#000', 0.18));
    ctx.fillStyle = g;
    ctx.beginPath();
    const sh = top;
    ctx.moveTo(-col.w / 2, baseTop - 8);
    ctx.lineTo(-col.w / 2, sh + 5);
    ctx.lineTo(-col.w / 2 + 4, sh);
    ctx.lineTo(col.w / 2 - 3, sh + 4);
    ctx.lineTo(col.w / 2, sh + 10);
    ctx.lineTo(col.w / 2, baseTop - 8);
    ctx.closePath();
    ctx.fill();
    // flutes
    ctx.strokeStyle = 'rgba(0,7,11,.25)';
    ctx.lineWidth = 0.8;
    for (let f = 1; f < 4; f++) {
      const fx = -col.w / 2 + f * (col.w / 4);
      ctx.beginPath(); ctx.moveTo(fx, baseTop - 10); ctx.lineTo(fx + 1, sh + 7); ctx.stroke();
    }
    // runes
    if (c === 1) {
      ctx.strokeStyle = rgba(pal.accent, 0.42);
      ctx.lineWidth = 1.1;
      for (let k = 0; k < 3; k++) {
        const yy = sh + 38 + k * 27;
        ctx.beginPath();
        ctx.moveTo(-7, yy); ctx.lineTo(6, yy); ctx.lineTo(-3, yy + 8); ctx.lineTo(7, yy + 15);
        ctx.stroke();
      }
      localGlow(ctx, 0, sh + 66, 32, pal.accent, 0.15);
    }
    ctx.restore();
    // capital or broken top
    if (c === 1) {
      block(ctx, pal, col.x - col.w / 2 - 7, top - 2, col.w + 14, 10, 0.07, 1);
      block(ctx, pal, col.x - col.w / 2 - 10, top + 8, col.w + 20, 7, 0.04, 1);
    }
    crack(ctx, col.x + 2, top + 16, 40, col.crack);
  }
  // fallen drum
  ctx.save();
  ctx.translate(42, 34);
  ctx.rotate(0.18);
  block(ctx, pal, -24, -10, 50, 17, 0.05, 3);
  ctx.strokeStyle = 'rgba(0,6,10,.3)';
  ctx.beginPath(); ctx.ellipse(25, -1.5, 5, 8, 0, 0, TAU); ctx.stroke();
  ctx.restore();
  // coral + kelp
  drawRuinGrowth(ctx, obj, pal, 80);
}

/* ------------------------------------------------------------------ */
function drawArch(r, obj, pal) {
  const ctx = r.ctx;
  block(ctx, pal, -96, 34, 38, 18, 0.03, 2);
  block(ctx, pal, 58, 34, 38, 18, 0.03, 2);
  // pillars
  for (const x of [-84, 72]) {
    const g = stoneGrad(ctx, pal, x, -90, x + 28, 38, 0.07);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(x, 36); ctx.lineTo(x + 2, -82); ctx.lineTo(x + 26, -76); ctx.lineTo(x + 28, 36); ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,6,10,.28)'; ctx.stroke();
    ctx.strokeStyle = rgba(pal.rim, 0.1);
    ctx.beginPath(); ctx.moveTo(x + 3, 32); ctx.lineTo(x + 4, -78); ctx.stroke();
  }
  // arch
  ctx.strokeStyle = stoneGrad(ctx, pal, -90, -100, 90, -20, 0.08);
  ctx.lineWidth = 19;
  ctx.beginPath();
  ctx.moveTo(-86, -70);
  ctx.bezierCurveTo(-74, -148, 66, -154, 86, -72);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(0,6,10,.32)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 5; i++) {
    const x = -68 + i * 34;
    const y = -110 - Math.sin((x + 86) / 172 * Math.PI) * 18;
    ctx.beginPath(); ctx.moveTo(x, y - 9); ctx.lineTo(x + 2, y + 9); ctx.stroke();
  }
  // broken keystone
  ctx.fillStyle = stoneGrad(ctx, pal, -12, -154, 18, -115, 0.07);
  ctx.beginPath(); ctx.moveTo(-10, -145); ctx.lineTo(14, -151); ctx.lineTo(9, -123); ctx.lineTo(-6, -126); ctx.closePath(); ctx.fill();
  // runes
  ctx.strokeStyle = rgba(pal.accent, 0.32); ctx.lineWidth = 1.2;
  for (let k = 0; k < 2; k++) {
    const y = -46 + k * 18;
    ctx.beginPath(); ctx.moveTo(-18, y); ctx.lineTo(18, y); ctx.moveTo(-11, y + 7); ctx.lineTo(11, y - 7); ctx.stroke();
  }
  localGlow(ctx, 0, -112, 60, pal.accent, 0.09);
  drawRuinGrowth(ctx, obj, pal, 44);
}

/* ------------------------------------------------------------------ */
function drawSlab(r, obj, pal) {
  const ctx = r.ctx;
  ctx.save();
  ctx.rotate(-0.24);
  block(ctx, pal, -56, -72, 112, 92, 0.06, 4);
  ctx.strokeStyle = 'rgba(0,6,10,.3)';
  ctx.lineWidth = 1.1;
  ctx.beginPath(); ctx.arc(0, -26, 24, 0, TAU); ctx.stroke();
  ctx.beginPath(); ctx.arc(0, -26, 14, 0, TAU); ctx.stroke();
  ctx.strokeStyle = rgba(pal.accent, 0.34);
  ctx.lineWidth = 1.2;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(-24 + i * 18, -4);
    ctx.lineTo(-16 + i * 14, 10);
    ctx.lineTo(-22 + i * 12, 24);
    ctx.stroke();
  }
  localGlow(ctx, 0, -26, 48, pal.accent, 0.08);
  ctx.restore();
  // shards at base
  ctx.fillStyle = stoneGrad(ctx, pal, -60, 20, 60, 44, 0.03);
  ctx.beginPath(); ctx.moveTo(-70, 38); ctx.lineTo(-28, 22); ctx.lineTo(30, 28); ctx.lineTo(58, 44); ctx.closePath(); ctx.fill();
  drawRuinGrowth(ctx, obj, pal, 34);
}

/* ------------------------------------------------------------------ */
function drawWreck(r, obj, pal) {
  const ctx = r.ctx;
  const t = r.time;
  ctx.rotate(-0.08);
  // deep shadow
  ctx.fillStyle = 'rgba(0,4,8,.32)';
  ctx.beginPath(); ctx.ellipse(0, 58, 210, 32, 0, 0, TAU); ctx.fill();

  // hull
  const hull = ctx.createLinearGradient(0, -38, 0, 46);
  hull.addColorStop(0, mixColor('#2a4650', pal.rim, 0.06));
  hull.addColorStop(0.36, '#17313a');
  hull.addColorStop(1, '#050e13');
  ctx.fillStyle = hull;
  ctx.beginPath();
  ctx.moveTo(-142, -6);
  ctx.bezierCurveTo(-110, -44, 20, -54, 112, -28);
  ctx.bezierCurveTo(160, -17, 178, 4, 168, 18);
  ctx.bezierCurveTo(120, 44, -20, 48, -110, 38);
  ctx.bezierCurveTo(-160, 32, -164, 18, -142, -6);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,7,10,.5)';
  ctx.lineWidth = 1.4;
  ctx.stroke();

  // hull planks and ribs
  ctx.save();
  ctx.strokeStyle = 'rgba(0,7,11,.26)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 7; i++) {
    ctx.beginPath();
    ctx.moveTo(-128 + i * 7, -2 + i * 5);
    ctx.bezierCurveTo(-40, -34 + i * 11, 70, -30 + i * 9, 156, 6 + i * 3);
    ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(139,225,220,.075)';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.moveTo(-90 + i * 48, -30);
    ctx.lineTo(-78 + i * 48, 38);
    ctx.stroke();
  }
  ctx.restore();

  // broken gap in the hull
  ctx.fillStyle = '#02080c';
  ctx.beginPath();
  ctx.moveTo(-62, 2);
  ctx.lineTo(-30, -12);
  ctx.lineTo(-4, 4);
  ctx.lineTo(-18, 26);
  ctx.lineTo(-44, 32);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(120,210,205,.12)';
  ctx.stroke();
  // Splinters
  ctx.fillStyle = '#122830';
  for (const [x, y, a] of [[-58, -2, -0.4], [-24, -10, 0.2], [-8, 18, 0.9]]) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(a); ctx.fillRect(-3, -8, 5, 18); ctx.restore();
  }

  // portholes
  for (let i = 0; i < 4; i++) {
    const x = -112 + i * 47, y = 4 + i * 1.8;
    ctx.beginPath(); ctx.arc(x, y, 6.5, 0, TAU); ctx.fillStyle = '#061014'; ctx.fill();
    ctx.strokeStyle = rgba(pal.accent, 0.7); ctx.lineWidth = 1.3; ctx.stroke();
    localGlow(ctx, x, y, 22, pal.accent, 0.22 + 0.06 * Math.sin(t * 1.4 + i));
    ctx.beginPath(); ctx.arc(x - 1, y - 1, 2.4, 0, TAU); ctx.fillStyle = rgba('#ffe0a0', 0.55); ctx.fill();
  }

  // Deck rail / bowsprit.
  ctx.strokeStyle = 'rgba(120,210,205,.17)';
  ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.moveTo(-110, -20); ctx.quadraticCurveTo(36, -45, 145, -20); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(165, 10); ctx.lineTo(214, -6); ctx.stroke();

  // Mast, snapped and tilted.
  ctx.save();
  ctx.translate(12, -30);
  ctx.rotate(0.18);
  const mast = ctx.createLinearGradient(-4, 0, 4, 0);
  mast.addColorStop(0, '#081319'); mast.addColorStop(0.5, '#2a454d'); mast.addColorStop(1, '#071016');
  ctx.fillStyle = mast;
  ctx.beginPath(); ctx.moveTo(-4, 0); ctx.lineTo(-2.4, -205); ctx.lineTo(3.4, -208); ctx.lineTo(4.5, 0); ctx.closePath(); ctx.fill();
  // yardarm
  ctx.save();
  ctx.translate(0, -155); ctx.rotate(-0.05);
  ctx.fillStyle = '#13282f';
  ctx.fillRect(-78, -2, 156, 5);
  ctx.restore();
  // torn sail
  ctx.fillStyle = 'rgba(103,157,157,.12)';
  ctx.beginPath();
  ctx.moveTo(-67, -151);
  ctx.bezierCurveTo(-42, -112, -23, -54, -30, -10);
  ctx.lineTo(-12, -34);
  ctx.bezierCurveTo(-20, -82, -12, -120, -4, -150);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(137,218,210,.1)';
  ctx.lineWidth = 0.8;
  ctx.beginPath(); ctx.moveTo(-63, -148); ctx.quadraticCurveTo(-38, -92, -30, -16); ctx.stroke();
  // rigging
  ctx.strokeStyle = 'rgba(124,205,200,.12)';
  ctx.lineWidth = 0.7;
  ctx.beginPath(); ctx.moveTo(0, -200); ctx.lineTo(-128, -24); ctx.moveTo(0, -200); ctx.lineTo(142, -24); ctx.stroke();
  ctx.restore();

  // coral growth on the wreck
  drawRuinGrowth(ctx, obj, pal, 88);
  // hanging weed from the rail
  ctx.strokeStyle = rgba(pal.kelp, 0.5);
  ctx.lineWidth = 1.4;
  for (let i = 0; i < 4; i++) {
    const x = -80 + i * 42;
    ctx.beginPath();
    ctx.moveTo(x, 3);
    ctx.bezierCurveTo(x + Math.sin(t * 0.5 + i) * 16, 30, x - 8 + Math.sin(t * 0.4 + i) * 20, 52, x + Math.sin(t * 0.6 + i) * 22, 76);
    ctx.stroke();
  }
  // A few lazy bubbles from the wreck.
  for (let i = 0; i < 5; i++) {
    const ph = (t * 0.14 + i * 0.2) % 1;
    ctx.globalAlpha = (1 - ph) * 0.35;
    ctx.strokeStyle = 'rgba(208,250,255,.7)';
    ctx.beginPath();
    ctx.arc(-40 + Math.sin(t + i * 2) * 30, 20 - ph * 130, 1.5 + i * 0.5, 0, TAU);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
}

/* ------------------------------------------------------------------ */
function drawVault(r, obj, pal) {
  const ctx = r.ctx;
  // stone plinth
  block(ctx, pal, -72, 34, 144, 18, 0.03, 3);
  block(ctx, pal, -88, 50, 176, 13, 0.02, 2);
  // giant crystals
  const crystal = (x, y, w, h, hue, tilt) => {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(tilt);
    const g = ctx.createLinearGradient(0, 0, w, -h);
    g.addColorStop(0, rgba(mixColor(hue, '#001018', 0.38), 0.96));
    g.addColorStop(0.45, rgba(hue, 0.86));
    g.addColorStop(1, rgba(mixColor(hue, '#ffffff', 0.55), 0.62));
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-w / 2, 0);
    ctx.lineTo(-w * 0.42, -h * 0.52);
    ctx.lineTo(0, -h);
    ctx.lineTo(w * 0.34, -h * 0.45);
    ctx.lineTo(w / 2, 0);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = rgba('#ffffff', 0.25);
    ctx.lineWidth = 0.8;
    ctx.stroke();
    ctx.strokeStyle = rgba(mixColor(hue, '#ffffff', 0.65), 0.36);
    ctx.beginPath(); ctx.moveTo(-1, -h * 0.94); ctx.lineTo(-2, -h * 0.1); ctx.stroke();
    localGlow(ctx, 0, -h * 0.5, h * 0.8, hue, 0.16);
    ctx.restore();
  };
  const hue = mixColor(pal.coral[1], '#c9a6ff', 0.5);
  crystal(-34, 34, 30, 160, hue, -0.2);
  crystal(20, 36, 42, 118, pal.coral[0], 0.18);
  crystal(52, 38, 24, 78, pal.accent, 0.32);
  crystal(-62, 40, 18, 64, pal.accent, -0.4);
  for (let i = 0; i < 7; i++) {
    const a = r.time * 0.4 + i * 1.9;
    localGlow(ctx, Math.cos(a) * 70, -10 + Math.sin(a) * 34, 12, pal.accent, 0.16);
  }
  drawRuinGrowth(ctx, obj, pal, 66);
}

/* ------------------------------------------------------------------ */
function drawTemple(r, obj, pal) {
  const ctx = r.ctx;
  const t = r.time;
  // silhouette behind the gate
  ctx.fillStyle = 'rgba(0,4,8,.55)';
  ctx.beginPath();
  ctx.moveTo(-150, 120); ctx.lineTo(-150, -120); ctx.lineTo(-100, -220); ctx.lineTo(0, -286);
  ctx.lineTo(104, -214); ctx.lineTo(152, -110); ctx.lineTo(152, 120); ctx.closePath(); ctx.fill();

  // plinth steps
  block(ctx, pal, -142, 98, 284, 22, 0.03, 2);
  block(ctx, pal, -126, 78, 252, 24, 0.04, 2);
  block(ctx, pal, -110, 58, 220, 23, 0.05, 2);
  // carved step glyphs
  ctx.strokeStyle = rgba(pal.accent, 0.25);
  ctx.lineWidth = 1;
  for (let i = 0; i < 7; i++) {
    const x = -92 + i * 30;
    ctx.beginPath(); ctx.moveTo(x, 99); ctx.lineTo(x + 8, 109); ctx.lineTo(x + 2, 116); ctx.stroke();
  }

  // gate columns
  const colXs = [-104, -56, 56, 104];
  for (let c = 0; c < colXs.length; c++) {
    const x = colXs[c];
    const w = 19;
    const broken = c === 3;
    const top = broken ? -90 : -180;
    const g = ctx.createLinearGradient(x - w / 2, 0, x + w / 2, 0);
    g.addColorStop(0, mixColor(pal.rockBottom, '#000', 0.1));
    g.addColorStop(0.36, mixColor(pal.rockTop, pal.rim, 0.08));
    g.addColorStop(0.72, mixColor(pal.rockTop, pal.rockBottom, 0.46));
    g.addColorStop(1, mixColor(pal.rockBottom, '#000', 0.2));
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(x - w / 2, 62);
    ctx.lineTo(x - w / 2, top + 8);
    ctx.lineTo(x - w / 2 + 4, top);
    ctx.lineTo(x + w / 2 - 2, top + 7);
    ctx.lineTo(x + w / 2, top + 12);
    ctx.lineTo(x + w / 2, 62);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,7,10,.4)';
    ctx.lineWidth = 1;
    ctx.stroke();
    // capitals
    if (!broken) {
      block(ctx, pal, x - w / 2 - 5, top - 2, w + 10, 8, 0.08, 1);
      block(ctx, pal, x - w / 2 - 8, top + 6, w + 16, 6, 0.04, 1);
    }
    // glyph strip
    ctx.strokeStyle = rgba(pal.accent, 0.3);
    ctx.lineWidth = 1;
    for (let k = 0; k < 4; k++) {
      const y = -30 + k * 20;
      ctx.beginPath(); ctx.moveTo(x - 4, y); ctx.lineTo(x + 4, y - 3); ctx.lineTo(x + 1, y + 6); ctx.stroke();
    }
    localGlow(ctx, x, -20, 30, pal.accent, 0.04);
    crack(ctx, x + 2, top + 14, 34, c + 1.9);
  }

  // lintel
  block(ctx, pal, -124, -208, 248, 30, 0.06, 2);
  block(ctx, pal, -112, -236, 224, 30, 0.055, 2);
  // pediment
  ctx.fillStyle = stoneGrad(ctx, pal, -80, -300, 80, -236, 0.06);
  ctx.beginPath();
  ctx.moveTo(-104, -236); ctx.lineTo(0, -308); ctx.lineTo(104, -236); ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,7,11,.34)'; ctx.lineWidth = 1.1; ctx.stroke();
  // carved sigil on pediment
  ctx.strokeStyle = rgba(pal.accent, 0.24);
  ctx.lineWidth = 1.3;
  ctx.beginPath();
  ctx.arc(0, -264, 15, 0, TAU);
  ctx.moveTo(0, -282); ctx.lineTo(0, -246);
  ctx.moveTo(-13, -264); ctx.lineTo(13, -264);
  ctx.stroke();
  localGlow(ctx, 0, -264, 55, pal.accent, 0.1);

  // central portal
  const portal = ctx.createLinearGradient(0, -170, 0, 60);
  portal.addColorStop(0, 'rgba(0,3,7,.88)');
  portal.addColorStop(0.72, 'rgba(1,7,12,.95)');
  portal.addColorStop(1, 'rgba(0,2,5,1)');
  ctx.fillStyle = portal;
  ctx.beginPath();
  ctx.moveTo(-42, 60);
  ctx.lineTo(-42, -132);
  ctx.quadraticCurveTo(0, -194, 42, -132);
  ctx.lineTo(42, 60);
  ctx.closePath();
  ctx.fill();
  // portal runes
  ctx.strokeStyle = rgba(pal.accent, 0.5);
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(-42, -128);
  ctx.quadraticCurveTo(0, -184, 42, -128);
  ctx.stroke();
  for (let i = 0; i < 5; i++) {
    const a = -0.72 + i * 0.16;
    const x = Math.sin(a) * 52;
    const y = -146 + Math.cos(a) * 30;
    ctx.beginPath(); ctx.arc(x, y, 1.5, 0, TAU); ctx.fillStyle = rgba(pal.accent, 0.55); ctx.fill();
    localGlow(ctx, x, y, 10, pal.accent, 0.25);
  }
  // inner glow
  const inGlow = ctx.createRadialGradient(0, -60, 0, 0, -60, 70);
  inGlow.addColorStop(0, rgba(pal.accent, 0.2 + 0.05 * Math.sin(t * 0.8)));
  inGlow.addColorStop(1, rgba(pal.accent, 0));
  ctx.fillStyle = inGlow;
  ctx.fillRect(-80, -160, 160, 200);

  drawRuinGrowth(ctx, obj, pal, 90);
  // drifting motes
  for (let i = 0; i < 12; i++) {
    const a = i * 2.7;
    const x = Math.sin(a + t * 0.18) * 120;
    const y = -150 + Math.cos(a * 1.4 + t * 0.15) * 90;
    ctx.fillStyle = rgba(pal.accent, 0.3 + 0.25 * Math.sin(t + i));
    ctx.beginPath(); ctx.arc(x, y, 1.2, 0, TAU); ctx.fill();
  }
}

/* ------------------------------------------------------------------ */
function drawBones(r, obj, pal) {
  const ctx = r.ctx;
  const bone = mixColor('#c9d5c7', pal.rim, 0.12);
  const boneDark = mixColor('#929e93', pal.rockBottom, 0.36);
  ctx.save();
  ctx.rotate(-0.06);
  // skull
  const g = ctx.createLinearGradient(-170, -80, -80, 30);
  g.addColorStop(0, bone);
  g.addColorStop(0.62, mixColor(bone, boneDark, 0.5));
  g.addColorStop(1, boneDark);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-168, 10);
  ctx.bezierCurveTo(-158, -52, -102, -76, -66, -44);
  ctx.bezierCurveTo(-48, -28, -52, 2, -72, 18);
  ctx.lineTo(-158, 34);
  ctx.bezierCurveTo(-176, 30, -180, 18, -168, 10);
  ctx.closePath();
  ctx.fill();
  // jaw
  ctx.save();
  ctx.translate(-100, 14); ctx.rotate(-0.16);
  ctx.fillStyle = boneDark;
  r.blobPath(0, 16, 44, 12, 3.2, 9, 0.16);
  ctx.fill();
  ctx.restore();
  // eye
  ctx.fillStyle = 'rgba(2,8,12,.8)';
  ctx.beginPath(); ctx.ellipse(-116, -26, 13, 9, -0.2, 0, TAU); ctx.fill();
  ctx.fillStyle = rgba(pal.accent, 0.35);
  ctx.beginPath(); ctx.arc(-116, -26, 3, 0, TAU); ctx.fill();
  localGlow(ctx, -116, -26, 30, pal.accent, 0.09);
  // teeth
  ctx.fillStyle = '#dbe6d8';
  for (let i = 0; i < 7; i++) {
    ctx.beginPath();
    ctx.moveTo(-142 + i * 9, 24);
    ctx.lineTo(-138 + i * 9, 38);
    ctx.lineTo(-134 + i * 9, 24);
    ctx.closePath(); ctx.fill();
  }

  // spine
  ctx.strokeStyle = bone;
  ctx.lineWidth = 11;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-66, -6);
  ctx.bezierCurveTo(10, -18, 90, 2, 150, 22);
  ctx.stroke();
  ctx.strokeStyle = boneDark;
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(-60, -8); ctx.bezierCurveTo(20, -20, 92, 0, 148, 20); ctx.stroke();
  // vertebrae
  for (let i = 0; i < 9; i++) {
    const x = -50 + i * 22;
    const y = -10 + i * 3;
    ctx.fillStyle = boneDark;
    ctx.beginPath(); ctx.ellipse(x, y, 8, 9, 0.1, 0, TAU); ctx.fill();
  }
  // ribs
  ctx.strokeStyle = bone;
  ctx.lineWidth = 4.6;
  for (let i = 0; i < 7; i++) {
    const x = -34 + i * 24;
    const len = 76 + i * 8;
    ctx.beginPath();
    ctx.moveTo(x, -9 + i * 3);
    ctx.bezierCurveTo(x - 22, -42 - i * 2, x - 36, -len, x + 8, -len - 12);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, -9 + i * 3);
    ctx.bezierCurveTo(x + 18, 28 + i * 2, x + 28, len * 0.8, x - 12, len * 0.88 + 8);
    ctx.stroke();
  }
  ctx.restore();
  // algae
  drawRuinGrowth(ctx, obj, pal, 72);
}

/* ------------------------------------------------------------------ */
function drawArchive(r, obj, pal) {
  const ctx = r.ctx;
  const t = r.time;
  // stone ring, broken in places
  ctx.save();
  ctx.rotate(0.05);
  ctx.strokeStyle = stoneGrad(ctx, pal, -100, -100, 100, 100, 0.07);
  ctx.lineWidth = 22;
  ctx.beginPath();
  ctx.arc(0, -30, 84, Math.PI * 0.12, Math.PI * 1.82);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(0,6,10,.35)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 9; i++) {
    const a = Math.PI * 0.14 + i / 9 * Math.PI * 1.66;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * 73, -30 + Math.sin(a) * 73);
    ctx.lineTo(Math.cos(a) * 95, -30 + Math.sin(a) * 95);
    ctx.stroke();
  }
  // broken section
  ctx.fillStyle = 'rgba(0,4,8,.65)';
  ctx.beginPath();
  ctx.moveTo(76, -86); ctx.lineTo(102, -66); ctx.lineTo(86, -30); ctx.lineTo(66, -46); ctx.closePath(); ctx.fill();
  ctx.restore();
  // portal void
  const portal = ctx.createRadialGradient(0, -30, 2, 0, -30, 74);
  portal.addColorStop(0, 'rgba(2,6,12,.98)');
  portal.addColorStop(0.7, 'rgba(2,7,13,.9)');
  portal.addColorStop(1, rgba(pal.accent, 0.12));
  ctx.fillStyle = portal;
  ctx.beginPath(); ctx.arc(0, -30, 72, 0, TAU); ctx.fill();
  // spiral light in the gate
  ctx.strokeStyle = rgba(pal.accent, 0.12);
  ctx.lineWidth = 1;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.arc(0, -30, 18 + i * 16 + Math.sin(t * 0.6 + i) * 4, t * 0.15 + i, t * 0.15 + i + 3.9);
    ctx.stroke();
  }
  // runic lights around the ring
  for (let i = 0; i < 8; i++) {
    const a = Math.PI * 0.18 + i / 8 * Math.PI * 1.64;
    const x = Math.cos(a) * 84, y = -30 + Math.sin(a) * 84;
    const pulse = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(t * 1.2 + i * 1.7));
    ctx.fillStyle = rgba(pal.accent, 0.55 * pulse);
    ctx.beginPath(); ctx.arc(x, y, 1.8, 0, TAU); ctx.fill();
    localGlow(ctx, x, y, 17, pal.accent, 0.22 * pulse);
  }
  // base
  block(ctx, pal, -62, 44, 124, 18, 0.03, 2);
  // floor glyphs
  ctx.strokeStyle = rgba(pal.accent, 0.2);
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(-38, 54); ctx.lineTo(0, 46); ctx.lineTo(38, 54); ctx.stroke();
  drawRuinGrowth(ctx, obj, pal, 70);
}

/* ------------------------------------------------------------------ */
function drawRuinGrowth(ctx, obj, pal, spread) {
  const t = 0; // static silhouettes; movement comes from surrounding water
  const color = pal.coral[(obj.seed + 2) % pal.coral.length];
  // coral fans at the base
  for (let i = 0; i < 3; i++) {
    const x = Math.sin(obj.seed + i * 2.1) * spread;
    ctx.strokeStyle = rgba(color, 0.42);
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(x, 30);
    ctx.quadraticCurveTo(x + 11, 8, x + 4 + i * 2, -18);
    ctx.stroke();
    for (let j = 0; j < 3; j++) {
      const a = -0.8 + j * 0.6;
      ctx.beginPath();
      ctx.moveTo(x + 5, -8 - j * 3);
      ctx.lineTo(x + 5 + Math.cos(a) * 13, -8 - j * 3 + Math.sin(a) * 13);
      ctx.stroke();
    }
  }
  // moss
  ctx.fillStyle = rgba(pal.kelp, 0.2);
  ctx.beginPath(); ctx.ellipse(-spread * 0.4, 36, 42, 9, 0, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.ellipse(spread * 0.45, 39, 34, 8, 0, 0, TAU); ctx.fill();
  // kelp ribbons
  for (let i = 0; i < 4; i++) {
    const x = -spread * 0.7 + i * spread * 0.42;
    ctx.strokeStyle = rgba(pal.kelp, 0.28);
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    ctx.moveTo(x, 36);
    ctx.bezierCurveTo(x - 10, 10, x + 6, -12, x - 2, -30 - i * 5);
    ctx.stroke();
  }
  // glow motes around deep structures
  if (obj.zone === 'midnight' || obj.zone === 'abyss') {
    for (let i = 0; i < 6; i++) {
      const a = obj.seed + i * 2.4;
      const x = Math.sin(a) * spread * 0.9;
      const y = Math.cos(a * 1.3) * 36 - 4;
      localGlow(ctx, x, y, 13, pal.accent, 0.18);
      ctx.fillStyle = rgba(pal.accent, 0.55);
      ctx.beginPath(); ctx.arc(x, y, 1.4, 0, TAU); ctx.fill();
    }
  }
}

/* Living creatures. Each has a readable silhouette and readable intent. */
import { TAU, clamp, rgba, mixColor } from './utils.js';

export function drawCreature(r, c) {
  switch (c.type) {
    case 'school': drawSchool(r, c); break;
    case 'jelly': drawJelly(r, c); break;
    case 'shark': drawShark(r, c); break;
    case 'angler': drawAngler(r, c); break;
    case 'manta': drawManta(r, c); break;
    default: break;
  }
}

/* ------------------------------------------------------------------ */
function drawSchool(r, c) {
  const ctx = r.ctx;
  const [cx, cy] = r.screen(c.x, c.y);
  if (cx < -260 || cx > r.W + 260 || cy < -220 || cy > r.H + 220) return;
  const baseScale = r.zoom * c.size;
  const fleeBoost = c.flee > 0 ? 1.25 : 1;
  const dir = c.dir;
  ctx.save();
  for (let i = 0; i < c.fish.length; i++) {
    const f = c.fish[i];
    const t = r.time * (1.1 + f.speed * 0.5) + f.phase;
    const fx = cx + (f.dx + Math.sin(t * 0.55) * 8) * baseScale;
    const fy = cy + (f.dy + Math.cos(t * 0.7) * 6 - Math.sin(c.phase + t * 0.2) * 5) * baseScale;
    const s = baseScale * f.size * fleeBoost;
    ctx.save();
    ctx.translate(fx, fy);
    ctx.rotate(Math.sin(t * 1.4) * 0.07);
    ctx.scale(dir * s, s);
    const color = c.color;
    // tail
    const tail = Math.sin(t * 5.5) * 0.5;
    ctx.fillStyle = rgba(mixColor(color, '#063040', 0.25), 0.72);
    ctx.beginPath();
    ctx.moveTo(-9, 0);
    ctx.quadraticCurveTo(-14, -5 + tail * 2, -17, -4);
    ctx.quadraticCurveTo(-14, 0, -17, 5);
    ctx.quadraticCurveTo(-13, 4 - tail * 2, -9, 0);
    ctx.fill();
    // body
    const g = ctx.createLinearGradient(0, -4, 0, 4);
    g.addColorStop(0, rgba(mixColor(color, '#ffffff', 0.22), 0.9));
    g.addColorStop(0.55, rgba(color, 0.8));
    g.addColorStop(1, rgba(mixColor(color, '#04131b', 0.32), 0.75));
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(-1, 0, 10, 4.2, 0, 0, TAU);
    ctx.fill();
    // top fin
    ctx.fillStyle = rgba(color, 0.55);
    ctx.beginPath();
    ctx.moveTo(-2, -3.4); ctx.lineTo(2, -7); ctx.lineTo(5, -3); ctx.closePath();
    ctx.fill();
    // eye
    ctx.fillStyle = 'rgba(3,16,24,.8)';
    ctx.beginPath(); ctx.arc(6, -0.8, 1.1, 0, TAU); ctx.fill();
    ctx.restore();
  }
  // occasional silver glints along the school
  if (Math.sin(r.time * 0.7 + c.phase) > 0.86) {
    const f = c.fish[Math.floor(r.time * 2) % c.fish.length];
    r.drawGlow(cx + f.dx * baseScale, cy + f.dy * baseScale, c.color, 18, 0.16);
  }
  ctx.restore();
}

/* ------------------------------------------------------------------ */
function drawJelly(r, c) {
  const [sx, sy] = r.screen(c.x, c.y);
  if (sx < -220 || sx > r.W + 220 || sy < -260 || sy > r.H + 260) return;
  handleStun(r, c, sx, sy, c.size * 0.9);
  const bob = Math.sin(r.time * 0.8 + c.phase) * 7 * r.zoom;
  drawJellyBody(r, sx, sy + bob, c.size, c.color, c.phase, c.alpha, c.hazard);
}

export function drawAmbientJelly(r, jelly) {
  const [sx, sy] = r.screen(jelly.x, jelly.y, jelly.parallax);
  const bob = Math.sin(r.time * 0.5 + jelly.phase) * 12 * r.zoom;
  drawJellyBody(r, sx, sy + bob, jelly.size, jelly.color, jelly.phase, jelly.alpha, false, true);
}

function drawJellyBody(r, sx, sy, size, color, phase, alpha, hazard, background = false) {
  const ctx = r.ctx;
  const s = (size / 60) * r.zoom * (background ? 1 : 1);
  const pulse = 1 + Math.sin(r.time * 1.1 + phase) * 0.055;
  const glowAlpha = hazard ? 0.32 : 0.22;
  r.drawGlow(sx, sy - size * 0.22 * r.zoom, color, size * 1.65 * r.zoom, glowAlpha * (background ? 0.7 : 1));

  ctx.save();
  ctx.translate(sx, sy);
  ctx.scale(s, s);
  ctx.globalAlpha = alpha;

  // tentacles behind the bell
  const armCount = 6;
  for (let i = 0; i < armCount; i++) {
    const ox = -38 + i * 15;
    const len = 78 + (i % 3) * 26 + Math.sin(phase + i) * 8;
    const sway = Math.sin(r.time * 0.9 + phase + i * 0.8) * 15;
    const sway2 = Math.sin(r.time * 0.7 + phase * 1.3 + i) * 23;
    ctx.beginPath();
    ctx.moveTo(ox, 2);
    ctx.bezierCurveTo(ox + sway * 0.4, len * 0.4, ox + sway2 * 0.7, len * 0.75, ox + sway2, len);
    ctx.strokeStyle = rgba(color, 0.4);
    ctx.lineWidth = 1.7;
    ctx.lineCap = 'round';
    ctx.stroke();
    // bead
    ctx.fillStyle = rgba(color, 0.5);
    ctx.beginPath(); ctx.arc(ox + sway2, len, 1.5, 0, TAU); ctx.fill();
  }
  // ruffled oral arms
  for (let i = 0; i < 3; i++) {
    const ox = -18 + i * 18;
    const len = 64 + i * 12;
    const sway = Math.sin(r.time * 0.8 + phase + i * 1.2) * 20;
    ctx.beginPath();
    ctx.moveTo(ox, 0);
    ctx.bezierCurveTo(ox - 10 + sway * 0.3, len * 0.3, ox + 14 + sway * 0.6, len * 0.6, ox + sway, len);
    ctx.strokeStyle = rgba(mixColor(color, '#ffffff', 0.25), 0.36);
    ctx.lineWidth = 5 - i;
    ctx.stroke();
  }

  // bell
  ctx.save();
  ctx.scale(1, pulse);
  const g = ctx.createLinearGradient(0, -58, 0, 6);
  g.addColorStop(0, rgba(mixColor(color, '#ffffff', 0.55), 0.55));
  g.addColorStop(0.42, rgba(color, 0.32));
  g.addColorStop(1, rgba(color, 0.035));
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-42, 0);
  ctx.bezierCurveTo(-46, -35, -26, -56, 0, -56);
  ctx.bezierCurveTo(27, -56, 47, -34, 42, 0);
  ctx.bezierCurveTo(30, 7, 18, 10, 7, 7);
  ctx.bezierCurveTo(-7, 11, -20, 7, -29, 9);
  ctx.bezierCurveTo(-36, 8, -40, 4, -42, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = rgba(mixColor(color, '#ffffff', 0.6), 0.55);
  ctx.lineWidth = 1.6;
  ctx.stroke();

  // inner bell ribs
  ctx.strokeStyle = rgba(mixColor(color, '#ffffff', 0.5), 0.3);
  ctx.lineWidth = 1;
  for (let i = 0; i < 4; i++) {
    const x = -22 + i * 15;
    ctx.beginPath();
    ctx.moveTo(x, 2);
    ctx.quadraticCurveTo(x * 0.7, -30, x * 0.34, -48);
    ctx.stroke();
  }
  // luminous spots
  for (let i = 0; i < 5; i++) {
    const a = phase + i * 1.6;
    const x = Math.sin(a) * 25;
    const y = -20 + Math.cos(a * 1.3) * 12;
    const p = 0.4 + 0.6 * (0.5 + 0.5 * Math.sin(r.time * 2 + i));
    ctx.fillStyle = rgba(mixColor(color, '#ffffff', 0.7), 0.55 * p);
    ctx.beginPath(); ctx.arc(x, y, 1.7, 0, TAU); ctx.fill();
  }
  ctx.restore();
  ctx.restore();
}

/* ------------------------------------------------------------------ */
function drawShark(r, c) {
  const ctx = r.ctx;
  const [sx, sy] = r.screen(c.x, c.y);
  if (sx < -220 || sx > r.W + 220 || sy < -180 || sy > r.H + 180) return;
  handleStun(r, c, sx, sy, 74 * c.size);
  const s = r.zoom * c.size;
  const angle = c.angle || 0;
  const chasing = c.state === 'chase' || c.state === 'bite';
  ctx.save();
  ctx.translate(sx, sy);
  ctx.rotate(angle);
  if (Math.cos(angle) < 0) ctx.scale(1, -1);
  ctx.scale(s, s);

  // wake / glow
  if (chasing) {
    localGlow(ctx, 0, 0, 70, '#ff6b5e', 0.05);
  }

  // tail
  const swish = Math.sin(r.time * 7.5 + c.phase) * 0.34;
  ctx.save();
  ctx.translate(-55, 0);
  ctx.rotate(swish);
  ctx.fillStyle = mixColor('#17384a', '#04121b', 0.42);
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.quadraticCurveTo(-23, -17, -34, -24);
  ctx.quadraticCurveTo(-20, -3, -29, 4);
  ctx.quadraticCurveTo(-16, 11, -38, 28);
  ctx.quadraticCurveTo(-16, 13, 0, 2);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // pectoral fin (behind)
  ctx.fillStyle = mixColor('#1c4053', '#04121b', 0.35);
  ctx.beginPath();
  ctx.moveTo(7, 11);
  ctx.quadraticCurveTo(2, 35, -18, 43);
  ctx.quadraticCurveTo(-8, 20, -4, 10);
  ctx.closePath();
  ctx.fill();

  // body
  const g = ctx.createLinearGradient(0, -27, 0, 34);
  g.addColorStop(0, mixColor('#54798a', r.pal.rim, 0.1));
  g.addColorStop(0.34, '#2d5364');
  g.addColorStop(0.62, '#18384a');
  g.addColorStop(0.78, '#a7bcc0');
  g.addColorStop(1, '#c9d8d6');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(70, 2);
  ctx.bezierCurveTo(54, -17, 18, -29, -32, -23);
  ctx.bezierCurveTo(-48, -20, -53, -9, -55, 0);
  ctx.bezierCurveTo(-48, 9, -34, 17, -8, 22);
  ctx.bezierCurveTo(26, 26, 52, 17, 70, 2);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,8,14,.32)';
  ctx.lineWidth = 0.9;
  ctx.stroke();

  // dorsal fin
  ctx.fillStyle = mixColor('#2a4b5d', '#061823', 0.2);
  ctx.beginPath();
  ctx.moveTo(-8, -23);
  ctx.quadraticCurveTo(-16, -55, -25, -57);
  ctx.quadraticCurveTo(-20, -32, -22, -21);
  ctx.closePath();
  ctx.fill();
  // second dorsal
  ctx.beginPath();
  ctx.moveTo(-41, -16); ctx.quadraticCurveTo(-50, -34, -54, -31); ctx.quadraticCurveTo(-50, -18, -48, -13); ctx.closePath(); ctx.fill();
  // pelvic fin
  ctx.beginPath();
  ctx.moveTo(-20, 18); ctx.quadraticCurveTo(-27, 31, -35, 32); ctx.quadraticCurveTo(-29, 20, -26, 15); ctx.closePath(); ctx.fill();

  // belly line
  ctx.strokeStyle = 'rgba(230,245,242,.2)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(45, 13);
  ctx.bezierCurveTo(20, 19, -16, 18, -40, 8);
  ctx.stroke();

  // gill slits
  ctx.strokeStyle = 'rgba(6,20,28,.5)';
  ctx.lineWidth = 1.1;
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(26 - i * 4, -8);
    ctx.quadraticCurveTo(22 - i * 4, 0, 25 - i * 4, 7);
    ctx.stroke();
  }

  // eye + mouth
  const eyeY = -7;
  ctx.fillStyle = chasing ? '#ff765f' : 'rgba(3,12,17,.9)';
  ctx.beginPath(); ctx.arc(43, eyeY, 2.4, 0, TAU); ctx.fill();
  if (chasing) localGlow(ctx, 43, eyeY, 12, '#ff6a58', 0.3);

  ctx.strokeStyle = 'rgba(6,17,23,.65)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(68, 8);
  ctx.quadraticCurveTo(53, 13, 39, 10);
  ctx.stroke();
  if (chasing) {
    ctx.fillStyle = 'rgba(238,242,228,.8)';
    for (let i = 0; i < 5; i++) {
      const x = 44 + i * 4.2;
      ctx.beginPath(); ctx.moveTo(x, 11); ctx.lineTo(x + 1.5, 16); ctx.lineTo(x + 3, 11); ctx.closePath(); ctx.fill();
    }
  }
  // scars
  ctx.strokeStyle = 'rgba(190,228,225,.12)';
  ctx.beginPath(); ctx.moveTo(-2, -19); ctx.lineTo(8, -10); ctx.stroke();
  ctx.restore();
}

/* ------------------------------------------------------------------ */
function drawAngler(r, c) {
  const ctx = r.ctx;
  const [sx, sy] = r.screen(c.x, c.y);
  if (sx < -180 || sx > r.W + 180 || sy < -200 || sy > r.H + 200) return;
  handleStun(r, c, sx, sy, 60 * c.size);
  const s = r.zoom * c.size;
  const hunting = c.state === 'chase' || c.state === 'lunge';
  const lureGlow = mixColor(r.pal.accent, '#ffffff', 0.25);
  ctx.save();
  ctx.translate(sx, sy);
  ctx.scale((c.dir || 1) * s, s);
  const bob = Math.sin(r.time * 0.9 + c.phase) * 2.5;
  ctx.translate(0, bob);

  // rear glow
  r.drawGlow(sx, sy - 26 * s, lureGlow, 90 * c.size * r.zoom, hunting ? 0.28 : 0.16);

  // fins
  ctx.fillStyle = '#08141e';
  ctx.beginPath();
  ctx.moveTo(-20, 8); ctx.quadraticCurveTo(-45, 18, -54, 34); ctx.quadraticCurveTo(-30, 30, -13, 18); ctx.closePath(); ctx.fill();
  ctx.beginPath();
  ctx.moveTo(-5, -28); ctx.quadraticCurveTo(-12, -44, -26, -48); ctx.quadraticCurveTo(-19, -30, -18, -23); ctx.closePath(); ctx.fill();

  // body
  const g = ctx.createRadialGradient(-10, -18, 4, 0, 0, 56);
  g.addColorStop(0, mixColor('#264556', r.pal.rim, 0.08));
  g.addColorStop(0.55, '#102738');
  g.addColorStop(1, '#030c14');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(48, 3);
  ctx.bezierCurveTo(41, -26, 15, -42, -16, -35);
  ctx.bezierCurveTo(-40, -30, -48, -9, -42, 12);
  ctx.bezierCurveTo(-35, 33, -6, 44, 22, 33);
  ctx.bezierCurveTo(38, 26, 49, 16, 48, 3);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,5,9,.35)';
  ctx.lineWidth = 1;
  ctx.stroke();

  // tail fin
  ctx.fillStyle = '#07121b';
  ctx.beginPath();
  ctx.moveTo(-42, 2);
  ctx.quadraticCurveTo(-62, -9, -72, -5);
  ctx.quadraticCurveTo(-57, 5, -68, 17);
  ctx.quadraticCurveTo(-48, 12, -39, 9);
  ctx.closePath();
  ctx.fill();

  // jaw
  const jawOpen = hunting ? 8 + Math.sin(r.time * 8) * 2 : 4;
  const jaw = ctx.createLinearGradient(0, 12, 0, 34);
  jaw.addColorStop(0, '#261c1f');
  jaw.addColorStop(1, '#07070c');
  ctx.fillStyle = jaw;
  ctx.beginPath();
  ctx.moveTo(46, 4);
  ctx.lineTo(45, 17 + jawOpen);
  ctx.quadraticCurveTo(20, 30 + jawOpen, -6, 24 + jawOpen * 0.5);
  ctx.quadraticCurveTo(14, 15, 20, 10);
  ctx.closePath();
  ctx.fill();
  // teeth
  ctx.fillStyle = 'rgba(228,238,224,.85)';
  for (let i = 0; i < 6; i++) {
    const x = 38 - i * 7;
    const y = 12 + jawOpen * (x / 48);
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x - 1.4, y + 6.5 + (i % 2) * 2);
    ctx.lineTo(x - 3.2, y);
    ctx.closePath();
    ctx.fill();
  }
  for (let i = 0; i < 4; i++) {
    const x = 32 - i * 7;
    ctx.beginPath();
    ctx.moveTo(x, 16 + jawOpen * 0.7);
    ctx.lineTo(x - 1, 10 + jawOpen * 0.7);
    ctx.lineTo(x - 3, 16 + jawOpen * 0.7);
    ctx.closePath();
    ctx.fill();
  }

  // eye
  ctx.fillStyle = 'rgba(230,250,250,.9)';
  ctx.beginPath(); ctx.arc(17, -14, 3.2, 0, TAU); ctx.fill();
  ctx.fillStyle = '#041016';
  ctx.beginPath(); ctx.arc(17.5, -14, 1.7, 0, TAU); ctx.fill();
  if (hunting) {
    ctx.fillStyle = 'rgba(255,104,74,.7)';
    ctx.beginPath(); ctx.arc(17.5, -14, 2.2, 0, TAU); ctx.fill();
  }

  // lure stalk
  ctx.strokeStyle = 'rgba(10,31,42,.9)';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(-4, -37);
  ctx.bezierCurveTo(8, -62, 34, -70, 46, -55 + Math.sin(r.time * 1.3 + c.phase) * 5);
  ctx.stroke();
  const lx = 46;
  const ly = -55 + Math.sin(r.time * 1.3 + c.phase) * 5;
  localGlow(ctx, lx, ly, 20, lureGlow, 0.6);
  ctx.fillStyle = 'rgba(235,255,250,.92)';
  ctx.beginPath(); ctx.arc(lx, ly, 3, 0, TAU); ctx.fill();

  // lateral glow dots
  for (let i = 0; i < 4; i++) {
    ctx.fillStyle = rgba(r.pal.accent, 0.22 + 0.1 * Math.sin(r.time * 1.4 + i));
    ctx.beginPath(); ctx.arc(-24 + i * 12, 6 + i * 2, 1.2, 0, TAU); ctx.fill();
  }
  ctx.restore();
}

/* ------------------------------------------------------------------ */
function drawManta(r, c) {
  const ctx = r.ctx;
  const [sx, sy] = r.screen(c.x, c.y);
  if (sx < -450 || sx > r.W + 450 || sy < -360 || sy > r.H + 360) return;
  const s = r.zoom * c.size * 1.25;
  const flap = Math.sin(r.time * 0.8 + c.phase);
  ctx.save();
  ctx.translate(sx, sy);
  ctx.scale((c.dir || 1) * s, s);
  ctx.globalAlpha = 0.66;
  const body = ctx.createLinearGradient(0, -30, 0, 44);
  body.addColorStop(0, mixColor('#153b4b', r.pal.rim, 0.07));
  body.addColorStop(0.55, '#0a222f');
  body.addColorStop(1, '#04121b');
  ctx.fillStyle = body;
  // wings + body
  ctx.beginPath();
  ctx.moveTo(-6, -18);
  ctx.bezierCurveTo(-34, -58 - flap * 15, -102, -62 - flap * 34, -122, -30 - flap * 18);
  ctx.bezierCurveTo(-98, -14, -52, 2, -24, 8);
  ctx.bezierCurveTo(-11, 6, -3, 0, 0, -6);
  ctx.bezierCurveTo(3, 0, 11, 6, 24, 8);
  ctx.bezierCurveTo(52, 2, 98, -14, 122, -30 - flap * 18);
  ctx.bezierCurveTo(102, -62 - flap * 34, 34, -58 - flap * 15, 6, -18);
  ctx.closePath();
  ctx.fill();
  // cephalic lobes
  ctx.beginPath();
  ctx.moveTo(-8, -14);
  ctx.quadraticCurveTo(-18, -29, -28, -25);
  ctx.quadraticCurveTo(-22, -12, -12, -8);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(8, -14);
  ctx.quadraticCurveTo(18, -29, 28, -25);
  ctx.quadraticCurveTo(22, -12, 12, -8);
  ctx.closePath();
  ctx.fill();
  // underside hint
  ctx.fillStyle = 'rgba(132,191,194,.12)';
  ctx.beginPath();
  ctx.moveTo(-20, 2);
  ctx.quadraticCurveTo(0, 28, 20, 2);
  ctx.quadraticCurveTo(0, 12, -20, 2);
  ctx.fill();
  // tail
  ctx.strokeStyle = '#0b2633';
  ctx.lineWidth = 3.2;
  ctx.beginPath();
  ctx.moveTo(0, 6);
  ctx.quadraticCurveTo(8, 50, 2 + flap * 8, 96);
  ctx.stroke();
  // spots
  ctx.fillStyle = 'rgba(145,214,206,.13)';
  for (let i = 0; i < 7; i++) {
    const a = i * 1.7;
    ctx.beginPath();
    ctx.ellipse(Math.sin(a) * 54, -14 + Math.cos(a * 1.2) * 18, 3.2, 2, 0.2, 0, TAU);
    ctx.fill();
  }
  // eyes
  ctx.fillStyle = 'rgba(3,12,18,.9)';
  ctx.beginPath(); ctx.arc(-7, -19, 1.7, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.arc(7, -19, 1.7, 0, TAU); ctx.fill();
  ctx.restore();
}

/* ------------------------------------------------------------------ */
function handleStun(r, c, sx, sy, radius) {
  if (!(c.stun > 0)) return;
  const ctx = r.ctx;
  const t = r.time * 5;
  ctx.save();
  ctx.strokeStyle = 'rgba(112,255,240,.55)';
  ctx.lineWidth = 1.3;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.arc(sx, sy, radius + i * 12, t + i * 2.1, t + i * 2.1 + 1.4);
    ctx.stroke();
  }
  ctx.fillStyle = 'rgba(160,255,246,.65)';
  for (let i = 0; i < 4; i++) {
    const a = t * 0.6 + i * 1.7;
    ctx.beginPath(); ctx.arc(sx + Math.cos(a) * radius * 0.8, sy + Math.sin(a) * radius * 0.6, 1.6, 0, TAU); ctx.fill();
  }
  ctx.restore();
}

function localGlow(ctx, x, y, radius, color, alpha = 0.5) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, radius);
  g.addColorStop(0, rgba(color, alpha));
  g.addColorStop(0.4, rgba(color, alpha * 0.36));
  g.addColorStop(1, rgba(color, 0));
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(x, y, radius, 0, TAU); ctx.fill();
}

/* The player's salvage submarine — a warm yellow light in a very large dark. */
import { TAU, clamp, rgba, mixColor } from './utils.js';

function playerPose(r, game) {
  const p = game.player;
  const [sx, sy] = r.screen(p.x, p.y);
  const bob = Math.sin(game.time * 1.6 + 0.8) * 1.8 * r.zoom;
  const speed = Math.max(60, p.speed || 240);
  const tilt = clamp(p.vy / speed, -1, 1) * 0.23 + Math.sin(game.time * 1.1) * 0.012;
  return { sx, sy: sy + bob, tilt };
}

export function drawHeadlight(r, game) {
  const p = game.player;
  if (!p.lightsOn) return;
  const ctx = r.ctx;
  const { sx, sy, tilt } = playerPose(r, game);
  const facing = p.facing || 1;
  const lamp = p.lampScale || 1;
  const depth = clamp((game.camera.y - 900) / 2600, 0, 1);
  const len = (300 + 160 * lamp) * r.zoom;
  const spread = (0.32 + 0.03 * lamp);
  const wob = Math.sin(game.time * 0.9) * 0.012;

  ctx.save();
  ctx.translate(sx + facing * 22 * r.zoom, sy - 1 * r.zoom);
  const angle = facing === 1 ? tilt * 0.55 + wob : Math.PI - tilt * 0.55 - wob;
  ctx.rotate(angle);
  ctx.globalCompositeOperation = 'screen';

  // Broad cone.
  const grad = ctx.createLinearGradient(0, 0, len, 0);
  const strength = 0.19 + depth * 0.16;
  grad.addColorStop(0, `rgba(255,244,186,${strength + 0.08})`);
  grad.addColorStop(0.22, `rgba(255,234,165,${strength * 0.78})`);
  grad.addColorStop(0.62, `rgba(255,222,142,${strength * 0.28})`);
  grad.addColorStop(1, 'rgba(255,216,130,0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.moveTo(0, -14 * r.zoom);
  ctx.quadraticCurveTo(len * 0.36, -len * spread * 0.46, len, -len * spread);
  ctx.lineTo(len, len * spread);
  ctx.quadraticCurveTo(len * 0.36, len * spread * 0.46, 0, 14 * r.zoom);
  ctx.closePath();
  ctx.fill();

  // Hot inner cone.
  const inner = ctx.createLinearGradient(0, 0, len * 0.85, 0);
  inner.addColorStop(0, `rgba(255,251,220,${strength * 0.85})`);
  inner.addColorStop(0.4, `rgba(255,241,180,${strength * 0.2})`);
  inner.addColorStop(1, 'rgba(255,235,170,0)');
  ctx.fillStyle = inner;
  ctx.beginPath();
  ctx.moveTo(0, -7 * r.zoom);
  ctx.quadraticCurveTo(len * 0.32, -len * spread * 0.2, len * 0.82, -len * spread * 0.44);
  ctx.lineTo(len * 0.82, len * spread * 0.44);
  ctx.quadraticCurveTo(len * 0.32, len * spread * 0.2, 0, 7 * r.zoom);
  ctx.closePath();
  ctx.fill();

  // Lamp bloom.
  const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, 42 * r.zoom);
  glow.addColorStop(0, 'rgba(255,253,224,.7)');
  glow.addColorStop(0.3, 'rgba(255,234,160,.24)');
  glow.addColorStop(1, 'rgba(255,220,130,0)');
  ctx.fillStyle = glow;
  ctx.beginPath(); ctx.arc(0, 0, 42 * r.zoom, 0, TAU); ctx.fill();
  ctx.restore();
}

export function drawPlayer(r, game) {
  const ctx = r.ctx;
  const p = game.player;
  if (game.mode === 'title' && !game.titleSub) return;
  const { sx, sy, tilt } = playerPose(r, game);
  const facing = p.facing || 1;
  const invuln = p.invulnerable > 0;
  const flicker = invuln ? 0.55 + 0.45 * Math.abs(Math.sin(game.time * 18)) : 1;
  const boosting = p.boosting;

  const ctxGlow = ctx;
  ctxGlow.save();
  ctxGlow.globalAlpha = flicker;
  ctxGlow.translate(sx, sy);
  ctxGlow.scale(facing * r.zoom, r.zoom);
  ctxGlow.rotate(tilt);

  // Prop wash glow and exhaust.
  if (boosting) {
    const g = ctxGlow.createRadialGradient(-58, 2, 2, -58, 2, 42);
    g.addColorStop(0, 'rgba(255,241,190,.7)');
    g.addColorStop(0.3, 'rgba(255,193,92,.28)');
    g.addColorStop(1, 'rgba(255,166,50,0)');
    ctxGlow.fillStyle = g;
    ctxGlow.beginPath(); ctxGlow.arc(-58, 2, 42, 0, TAU); ctxGlow.fill();
    ctxGlow.fillStyle = 'rgba(255,221,140,.5)';
    ctxGlow.beginPath();
    ctxGlow.moveTo(-50, -4);
    ctxGlow.lineTo(-70 - Math.sin(game.time * 25) * 5, 2);
    ctxGlow.lineTo(-50, 8);
    ctxGlow.closePath();
    ctxGlow.fill();
  } else {
    const g = ctxGlow.createRadialGradient(-55, 2, 1, -55, 2, 22);
    g.addColorStop(0, 'rgba(255,232,160,.3)');
    g.addColorStop(1, 'rgba(255,210,120,0)');
    ctxGlow.fillStyle = g;
    ctxGlow.beginPath(); ctxGlow.arc(-55, 2, 22, 0, TAU); ctxGlow.fill();
  }

  // Propeller.
  const propSpin = game.time * (boosting ? 26 : 15);
  ctxGlow.save();
  ctxGlow.translate(-48, 1);
  const brass = ctxGlow.createLinearGradient(-4, -9, 4, 9);
  brass.addColorStop(0, '#f8dc8d');
  brass.addColorStop(0.5, '#b88023');
  brass.addColorStop(1, '#5c3a0e');
  ctxGlow.fillStyle = brass;
  ctxGlow.beginPath(); ctxGlow.arc(0, 0, 4, 0, TAU); ctxGlow.fill();
  for (let i = 0; i < 3; i++) {
    ctxGlow.save();
    ctxGlow.rotate(propSpin + i * TAU / 3);
    ctxGlow.beginPath();
    ctxGlow.ellipse(0, -8, 2.2, 7, 0.16, 0, TAU);
    ctxGlow.fillStyle = 'rgba(246,211,118,.72)';
    ctxGlow.fill();
    ctxGlow.restore();
  }
  ctxGlow.restore();

  // Tail fins.
  const finG = ctxGlow.createLinearGradient(-46, -18, -46, 18);
  finG.addColorStop(0, '#e0a62d');
  finG.addColorStop(1, '#8d5a10');
  ctxGlow.fillStyle = finG;
  ctxGlow.beginPath();
  ctxGlow.moveTo(-33, -13);
  ctxGlow.quadraticCurveTo(-49, -24, -53, -27);
  ctxGlow.quadraticCurveTo(-47, -10, -42, -5);
  ctxGlow.closePath();
  ctxGlow.fill();
  ctxGlow.beginPath();
  ctxGlow.moveTo(-33, 13);
  ctxGlow.quadraticCurveTo(-49, 24, -53, 27);
  ctxGlow.quadraticCurveTo(-47, 10, -42, 5);
  ctxGlow.closePath();
  ctxGlow.fill();

  // Hull.
  const hull = ctxGlow.createLinearGradient(0, -24, 0, 24);
  hull.addColorStop(0, '#fff0a1');
  hull.addColorStop(0.18, '#ffe078');
  hull.addColorStop(0.5, '#f5bb3d');
  hull.addColorStop(0.78, '#d48d20');
  hull.addColorStop(1, '#985c0d');
  ctxGlow.fillStyle = hull;
  ctxGlow.beginPath();
  ctxGlow.moveTo(47, 2);
  ctxGlow.bezierCurveTo(43, -15, 26, -23, 2, -23);
  ctxGlow.bezierCurveTo(-24, -23, -39, -15, -42, -4);
  ctxGlow.quadraticCurveTo(-45, 9, -34, 16);
  ctxGlow.bezierCurveTo(-13, 24, 24, 21, 40, 12);
  ctxGlow.quadraticCurveTo(46, 8, 47, 2);
  ctxGlow.closePath();
  ctxGlow.fill();
  ctxGlow.strokeStyle = 'rgba(54,32,3,.55)';
  ctxGlow.lineWidth = 1.2;
  ctxGlow.stroke();

  // Belly shadow / keel.
  const belly = ctxGlow.createLinearGradient(0, 0, 0, 22);
  belly.addColorStop(0, 'rgba(91,48,0,0)');
  belly.addColorStop(1, 'rgba(65,35,0,.42)');
  ctxGlow.fillStyle = belly;
  ctxGlow.beginPath();
  ctxGlow.moveTo(39, 12);
  ctxGlow.bezierCurveTo(19, 22, -14, 24, -33, 16);
  ctxGlow.bezierCurveTo(-16, 20, 12, 17, 31, 8);
  ctxGlow.closePath();
  ctxGlow.fill();
  ctxGlow.fillStyle = '#6b430c';
  ctxGlow.beginPath();
  ctxGlow.ellipse(4, 19, 27, 3.2, 0.02, 0, TAU);
  ctxGlow.fill();

  // Panel seams, rivets, white waterline.
  ctxGlow.strokeStyle = 'rgba(109,63,8,.28)';
  ctxGlow.lineWidth = 0.9;
  ctxGlow.beginPath();
  ctxGlow.moveTo(-36, -7);
  ctxGlow.quadraticCurveTo(-14, -19, 24, -17);
  ctxGlow.stroke();
  ctxGlow.beginPath();
  ctxGlow.moveTo(-31, 12);
  ctxGlow.quadraticCurveTo(-8, 6, 27, 8);
  ctxGlow.stroke();
  ctxGlow.strokeStyle = 'rgba(255,250,212,.4)';
  ctxGlow.lineWidth = 2;
  ctxGlow.beginPath();
  ctxGlow.moveTo(-28, 14);
  ctxGlow.quadraticCurveTo(-4, 20, 30, 13);
  ctxGlow.stroke();
  ctxGlow.fillStyle = 'rgba(103,59,4,.5)';
  for (const [x, y] of [[-30, -9], [-19, -13], [-19, 12], [-4, 15], [14, -16], [27, -8], [30, 9], [17, 16]]) {
    ctxGlow.beginPath(); ctxGlow.arc(x, y, 0.9, 0, TAU); ctxGlow.fill();
  }

  // Top skid / mast.
  ctxGlow.fillStyle = '#cd8f26';
  ctxGlow.beginPath();
  ctxGlow.moveTo(-20, -22); ctxGlow.lineTo(-17, -30); ctxGlow.lineTo(-11, -30); ctxGlow.lineTo(-9, -22); ctxGlow.closePath(); ctxGlow.fill();
  ctxGlow.strokeStyle = 'rgba(93,57,12,.85)';
  ctxGlow.lineWidth = 1.2;
  ctxGlow.beginPath(); ctxGlow.moveTo(-15, -29); ctxGlow.lineTo(-14, -42); ctxGlow.stroke();
  const mastLight = 0.7 + 0.3 * Math.sin(game.time * 3);
  ctxGlow.fillStyle = `rgba(112,255,235,${mastLight})`;
  ctxGlow.beginPath(); ctxGlow.arc(-14, -43, 1.7, 0, TAU); ctxGlow.fill();
  const mastGlow = ctxGlow.createRadialGradient(-14, -43, 0, -14, -43, 14);
  mastGlow.addColorStop(0, 'rgba(112,255,235,.35)');
  mastGlow.addColorStop(1, 'rgba(112,255,235,0)');
  ctxGlow.fillStyle = mastGlow;
  ctxGlow.beginPath(); ctxGlow.arc(-14, -43, 14, 0, TAU); ctxGlow.fill();

  // Sonar dish on top rear.
  ctxGlow.save();
  ctxGlow.translate(22, -22);
  ctxGlow.rotate(-0.3);
  ctxGlow.fillStyle = '#6f470c';
  ctxGlow.beginPath(); ctxGlow.ellipse(0, 0, 8, 2.6, 0, 0, TAU); ctxGlow.fill();
  ctxGlow.strokeStyle = 'rgba(255,231,150,.35)';
  ctxGlow.lineWidth = 0.8;
  ctxGlow.beginPath(); ctxGlow.ellipse(0, 0, 8, 2.6, 0, 0, TAU); ctxGlow.stroke();
  ctxGlow.restore();

  // Cockpit dome.
  const dome = ctxGlow.createRadialGradient(2, -25, 1, 8, -17, 18);
  dome.addColorStop(0, 'rgba(225,255,255,.92)');
  dome.addColorStop(0.3, 'rgba(121,238,243,.7)');
  dome.addColorStop(0.72, 'rgba(23,113,137,.86)');
  dome.addColorStop(1, 'rgba(6,52,75,.96)');
  ctxGlow.fillStyle = dome;
  ctxGlow.beginPath();
  ctxGlow.arc(8, -16, 14.5, Math.PI * 0.98, Math.PI * 2.08);
  ctxGlow.lineTo(22.2, -12);
  ctxGlow.arc(8, -16, 14.5, Math.PI * 0.04, Math.PI * 0.98);
  ctxGlow.closePath();
  ctxGlow.fill();
  ctxGlow.strokeStyle = '#dba52e';
  ctxGlow.lineWidth = 2.2;
  ctxGlow.stroke();
  // Dome highlight.
  ctxGlow.strokeStyle = 'rgba(240,255,255,.55)';
  ctxGlow.lineWidth = 1.1;
  ctxGlow.beginPath();
  ctxGlow.arc(5, -19, 9, Math.PI * 1.06, Math.PI * 1.62);
  ctxGlow.stroke();
  // Pilot silhouette.
  ctxGlow.fillStyle = 'rgba(2,24,34,.62)';
  ctxGlow.beginPath(); ctxGlow.arc(11, -17, 4.6, 0, TAU); ctxGlow.fill();
  ctxGlow.beginPath(); ctxGlow.ellipse(9, -8.5, 8, 4.4, -0.1, 0, Math.PI); ctxGlow.fill();

  // Side porthole.
  ctxGlow.fillStyle = '#082632';
  ctxGlow.beginPath(); ctxGlow.arc(-17, -4, 4.3, 0, TAU); ctxGlow.fill();
  ctxGlow.strokeStyle = 'rgba(248,209,112,.75)';
  ctxGlow.lineWidth = 1.4;
  ctxGlow.stroke();
  ctxGlow.fillStyle = 'rgba(167,248,255,.38)';
  ctxGlow.beginPath(); ctxGlow.arc(-18.3, -5.2, 1.3, 0, TAU); ctxGlow.fill();

  // Headlight housings.
  ctxGlow.fillStyle = '#6c450c';
  ctxGlow.beginPath(); ctxGlow.ellipse(43, 2, 3.8, 5, 0, 0, TAU); ctxGlow.fill();
  ctxGlow.fillStyle = '#fff9d6';
  ctxGlow.beginPath(); ctxGlow.arc(44, 2, 2.2, 0, TAU); ctxGlow.fill();
  const lens = ctxGlow.createRadialGradient(44, 2, 0, 44, 2, 15);
  lens.addColorStop(0, 'rgba(255,252,218,.8)');
  lens.addColorStop(1, 'rgba(255,241,170,0)');
  ctxGlow.fillStyle = lens;
  ctxGlow.beginPath(); ctxGlow.arc(44, 2, 15, 0, TAU); ctxGlow.fill();

  // Claw arm.
  ctxGlow.strokeStyle = '#c28a24';
  ctxGlow.lineWidth = 2.5;
  ctxGlow.lineCap = 'round';
  ctxGlow.beginPath();
  ctxGlow.moveTo(16, 18);
  ctxGlow.quadraticCurveTo(24, 27, 32, 24);
  ctxGlow.stroke();
  ctxGlow.strokeStyle = '#dcaa3a';
  ctxGlow.lineWidth = 1.7;
  ctxGlow.beginPath(); ctxGlow.moveTo(32, 24); ctxGlow.lineTo(37, 20); ctxGlow.moveTo(32, 24); ctxGlow.lineTo(37, 29); ctxGlow.stroke();
  ctxGlow.fillStyle = '#f6cf6a';
  ctxGlow.beginPath(); ctxGlow.arc(32, 24, 2, 0, TAU); ctxGlow.fill();

  // Warm rim light.
  ctxGlow.strokeStyle = 'rgba(255,252,211,.45)';
  ctxGlow.lineWidth = 1.2;
  ctxGlow.beginPath();
  ctxGlow.moveTo(30, -20);
  ctxGlow.quadraticCurveTo(45, -12, 46, 3);
  ctxGlow.stroke();

  // Damage smoke.
  if (p.health / p.healthMax < 0.35) {
    for (let i = 0; i < 2; i++) {
      const t = (game.time * 0.7 + i * 0.5) % 1;
      ctxGlow.globalAlpha = (1 - t) * 0.25;
      ctxGlow.fillStyle = '#07131a';
      ctxGlow.beginPath();
      ctxGlow.arc(-34 - t * 30, -8 - t * 22, 2 + t * 7, 0, TAU);
      ctxGlow.fill();
    }
    ctxGlow.globalAlpha = flicker;
  }
  ctxGlow.restore();
}

/* DOM interface: HUD, fabrication bay, overlays, touch joystick. */
import { UPGRADES, upgradesAt, TOTAL_CHESTS, depthAt } from './world.js';
import { formatTime, formatNumber, clamp } from './utils.js';

const $ = id => document.getElementById(id);
const svg = (id, cls = 'icon') => `<svg class="${cls}"><use href="#${id}"/></svg>`;

export class Hud {
  constructor(game) {
    this.game = game;
    this.toastTimers = new Set();
    this.bannerTimer = null;
    this.titleTimer = null;
    this.joy = { active: false, id: null };
    this.last = { oxygen: -1, hull: -1, depth: -1, salvage: -1, relics: -1, chests: -1, zone: '' };
    this.el = {
      hud: $('hud'),
      oxygenRow: $('oxygen-row'),
      hullRow: $('hull-row'),
      oxygenFill: $('oxygen-fill'),
      hullFill: $('hull-fill'),
      oxygenValue: $('oxygen-value'),
      hullValue: $('hull-value'),
      zoneName: $('zone-name'),
      depthValue: $('depth-value'),
      salvage: $('salvage-value'),
      relics: $('relic-value'),
      chests: $('chest-value'),
      objectiveText: $('objective-text'),
      objectiveCount: $('objective-count'),
      objectiveFill: $('objective-fill'),
      pressureWarning: $('pressure-warning'),
      ratingText: $('rating-text'),
      gaugeMarker: $('gauge-marker'),
      gaugeLabel: $('gauge-marker-label'),
      gaugeRating: $('gauge-rating'),
      sonarBtn: $('sonar-btn'),
      sonarCooldown: $('sonar-cooldown'),
      touchSonar: $('touch-sonar'),
      touchSonarCooldown: $('touch-sonar-cooldown'),
      boostBtn: $('boost-btn'),
      touchBoost: $('touch-boost'),
      interactWrap: $('interact-wrap'),
      interactBtn: $('interact-btn'),
      interactName: document.querySelector('.interact-copy small'),
      interactLabel: document.querySelector('.interact-copy strong'),
      toastStack: $('toast-stack'),
      zoneBanner: $('zone-banner'),
      bannerTitle: $('zone-banner-title'),
      bannerSub: $('zone-banner-sub'),
      saveIndicator: $('save-indicator'),
      title: $('title-screen'),
      titleStart: $('start-btn'),
      titleNew: $('new-btn'),
      titleHint: $('title-hint'),
      saveSummary: $('save-summary'),
      saveDepth: $('save-depth'),
      saveSalvage: $('save-salvage'),
      saveChests: $('save-chests'),
      fab: $('fabricator'),
      fabSalvage: $('fab-salvage'),
      fabGrid: $('upgrade-grid'),
      fabOxygen: $('fab-stat-oxygen'),
      fabHull: $('fab-stat-hull'),
      fabSpeed: $('fab-stat-speed'),
      fabDepth: $('fab-stat-depth'),
      repairBtn: $('repair-btn'),
      repairCost: $('repair-cost'),
      pause: $('pause-screen'),
      pauseDepth: $('pause-depth'),
      pauseChests: $('pause-chests'),
      pauseTime: $('pause-time'),
      gameover: $('gameover-screen'),
      overDepth: $('over-depth'),
      overChests: $('over-chests'),
      overLost: $('over-lost'),
      victory: $('victory-screen'),
      victoryDepth: $('victory-depth'),
      victoryChests: $('victory-chests'),
      victorySalvage: $('victory-salvage'),
      soundBtn: $('sound-btn'),
      pauseBtn: $('pause-btn'),
      upgradeBtn: $('upgrade-btn'),
      touchUpgrade: $('touch-upgrade'),
      joystick: $('joystick'),
      joystickKnob: $('joystick-knob'),
    };
    this.bind();
    this.setMuted(game.muted);
  }

  bind() {
    const g = this.game;
    this.el.titleStart.addEventListener('click', () => g.startGame());
    this.el.titleNew.addEventListener('click', () => g.newExpedition());
    this.el.soundBtn.addEventListener('click', () => g.toggleMute());
    this.el.pauseBtn.addEventListener('click', () => g.pauseGame());
    this.el.upgradeBtn.addEventListener('click', () => g.openFabricator());
    this.el.touchUpgrade.addEventListener('click', () => g.openFabricator());
    this.el.sonarBtn.addEventListener('click', () => g.triggerSonar());
    this.el.touchSonar.addEventListener('click', () => g.triggerSonar());
    this.el.interactBtn.addEventListener('click', () => g.interact());
    this.el.repairBtn.addEventListener('click', () => g.repairHull());

    const boostDown = e => { e.preventDefault(); g.setBoost(true); this.el.boostBtn.classList.add('active'); this.el.touchBoost.classList.add('active'); };
    const boostUp = () => { g.setBoost(false); this.el.boostBtn.classList.remove('active'); this.el.touchBoost.classList.remove('active'); };
    for (const btn of [this.el.boostBtn, this.el.touchBoost]) {
      btn.addEventListener('pointerdown', boostDown);
      btn.addEventListener('pointerup', boostUp);
      btn.addEventListener('pointercancel', boostUp);
      btn.addEventListener('pointerleave', boostUp);
    }
    window.addEventListener('pointerup', boostUp);

    this.el.fabGrid.addEventListener('click', e => {
      const btn = e.target.closest('[data-buy]');
      if (btn) g.buyUpgrade(btn.dataset.buy);
    });
    document.querySelectorAll('[data-close="fabricator"]').forEach(btn => btn.addEventListener('click', () => g.closeFabricator()));
    $('resume-btn').addEventListener('click', () => g.resumeGame());
    $('pause-save-btn').addEventListener('click', () => { g.saveGame(true); this.toast('Expedition saved', 'gold', 'i-anchor'); });
    $('pause-title-btn').addEventListener('click', () => g.returnToTitle());
    $('respawn-btn').addEventListener('click', () => g.respawn());
    $('victory-continue').addEventListener('click', () => g.continueExploring());
    $('victory-title').addEventListener('click', () => g.returnToTitle());

    // Joystick.
    const joy = this.el.joystick;
    const setFromPointer = e => {
      const rect = joy.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      let dx = (e.clientX - cx) / (rect.width * 0.35);
      let dy = (e.clientY - cy) / (rect.height * 0.35);
      const len = Math.hypot(dx, dy);
      if (len > 1) { dx /= len; dy /= len; }
      const dist = Math.min(1, len) * (rect.width * 0.28);
      const a = Math.atan2(dy, dx);
      const tx = Math.cos(a) * dist;
      const ty = Math.sin(a) * dist;
      this.el.joystickKnob.style.transform = `translate(${tx}px, ${ty}px)`;
      g.setJoystick(dx, dy);
    };
    joy.addEventListener('pointerdown', e => {
      if (this.joy.active) return;
      e.preventDefault();
      this.joy.active = true;
      this.joy.id = e.pointerId;
      joy.setPointerCapture(e.pointerId);
      setFromPointer(e);
    });
    joy.addEventListener('pointermove', e => {
      if (!this.joy.active || e.pointerId !== this.joy.id) return;
      e.preventDefault();
      setFromPointer(e);
    });
    const release = e => {
      if (!this.joy.active || (e && e.pointerId !== this.joy.id)) return;
      this.joy.active = false;
      this.joy.id = null;
      this.el.joystickKnob.style.transform = 'translate(0px, 0px)';
      g.setJoystick(0, 0);
    };
    joy.addEventListener('pointerup', release);
    joy.addEventListener('pointercancel', release);
    window.addEventListener('pointerup', release);
    joy.addEventListener('contextmenu', e => e.preventDefault());

    document.addEventListener('contextmenu', e => {
      if (e.target.closest('#joystick, #touch-controls')) e.preventDefault();
    });
  }

  setMuted(muted) {
    document.body.classList.toggle('muted', muted);
  }

  showTitle(save) {
    this.el.title.classList.remove('gone');
    this.el.hud.classList.add('is-hidden');
    if (save) {
      this.el.titleNew.classList.remove('is-hidden');
      this.el.saveSummary.classList.remove('is-hidden');
      this.el.saveDepth.textContent = `${formatNumber(save.stats.bestDepth)} m`;
      this.el.saveSalvage.textContent = `${formatNumber(save.salvage)} scrap`;
      this.el.saveChests.textContent = `${save.opened.length} / ${TOTAL_CHESTS} caches`;
      this.el.titleHint.textContent = 'Press ENTER to resume the expedition';
    } else {
      this.el.titleNew.classList.add('is-hidden');
      this.el.saveSummary.classList.add('is-hidden');
      this.el.titleHint.textContent = 'Press ENTER to dive';
    }
  }

  hideTitle() {
    this.el.title.classList.add('gone');
    this.el.hud.classList.remove('is-hidden');
  }

  showHud() {
    this.el.hud.classList.remove('is-hidden');
  }

  hideHud() {
    this.el.hud.classList.add('is-hidden');
  }

  sync() {
    const g = this.game, p = g.player, el = this.el;
    const o2 = Math.round(p.oxygen);
    const hp = Math.round(p.health);
    const depth = depthAt(p.y);
    if (o2 !== this.last.oxygen) {
      el.oxygenValue.textContent = o2;
      el.oxygenFill.style.width = `${clamp(p.oxygen / p.oxygenMax, 0, 1) * 100}%`;
      el.oxygenRow.classList.toggle('low', p.oxygen / p.oxygenMax < 0.32);
      el.oxygenRow.classList.toggle('critical', p.oxygen / p.oxygenMax < 0.14);
      this.last.oxygen = o2;
    }
    if (hp !== this.last.hull) {
      el.hullValue.textContent = hp;
      el.hullFill.style.width = `${clamp(p.health / p.healthMax, 0, 1) * 100}%`;
      el.hullRow.classList.toggle('low', p.health / p.healthMax < 0.34);
      el.hullRow.classList.toggle('critical', p.health / p.healthMax < 0.18);
      this.last.hull = hp;
    }
    if (depth !== this.last.depth) {
      el.depthValue.textContent = `${depth} m`;
      const pct = clamp(depth / 1850, 0, 1) * 100;
      el.gaugeMarker.style.top = `${pct}%`;
      el.gaugeLabel.textContent = `${depth}m`;
      this.last.depth = depth;
    }
    const zone = g.currentZone;
    if (zone && zone.id !== this.last.zone) {
      el.zoneName.textContent = zone.name.toUpperCase();
      const pip = document.querySelector('.zone-pip');
      if (pip) {
        pip.style.background = zone.palette.accent;
        pip.style.boxShadow = `0 0 8px ${zone.palette.accent}`;
      }
      this.last.zone = zone.id;
    }
    const sal = Math.round(g.salvage);
    if (sal !== this.last.salvage) { el.salvage.textContent = formatNumber(sal); this.last.salvage = sal; }
    if (g.relics !== this.last.relics) { el.relics.textContent = formatNumber(g.relics); this.last.relics = g.relics; }
    if (g.openedChests.size !== this.last.chests) {
      el.chests.textContent = `${g.openedChests.size}/${TOTAL_CHESTS}`;
      this.last.chests = g.openedChests.size;
    }

    const ratingPct = clamp(p.ratedDepth / 1850, 0, 1) * 100;
    el.gaugeRating.style.top = `${ratingPct}%`;
    el.pressureWarning.classList.toggle('is-hidden', !g.pressureOver || g.mode !== 'playing');
    if (g.pressureOver) el.ratingText.textContent = `Rated to ${p.ratedDepth} m · ascend now`;

    const cool = g.sonarCooldown > 0 ? g.sonarCooldown / g.sonarMax : 0;
    for (const [btn, cd] of [[el.sonarBtn, el.sonarCooldown], [el.touchSonar, el.touchSonarCooldown]]) {
      btn.classList.toggle('cooling', cool > 0);
      btn.style.setProperty('--cool', String(cool));
      if (cd) cd.style.setProperty('--cool', String(cool));
      btn.title = cool > 0 ? `Sonar recharging ${Math.ceil(g.sonarCooldown)}s` : 'Sonar pulse [Space]';
    }
  }

  setObjective(text, count, progress) {
    this.el.objectiveText.textContent = text;
    this.el.objectiveCount.textContent = count ?? `${this.game.openedChests.size} / ${TOTAL_CHESTS}`;
    this.el.objectiveFill.style.width = `${clamp(progress ?? (this.game.openedChests.size / TOTAL_CHESTS), 0, 1) * 100}%`;
  }

  setInteract(chest) {
    if (!chest) {
      this.el.interactWrap.classList.add('is-hidden');
      return;
    }
    this.el.interactName.textContent = chest.name.toUpperCase();
    this.el.interactLabel.textContent = 'Open chest';
    this.el.interactWrap.classList.remove('is-hidden');
  }

  bumpResource(kind) {
    const target = kind === 'relic' ? this.el.relics.parentElement : kind === 'chest' ? this.el.chests.parentElement : this.el.salvage.parentElement;
    if (!target) return;
    target.classList.remove('bump');
    void target.offsetWidth;
    target.classList.add('bump');
  }

  toast(text, kind = '', icon = 'i-relic') {
    const div = document.createElement('div');
    div.className = `toast ${kind}`;
    div.innerHTML = `${svg(icon)}<span>${text}</span>`;
    this.el.toastStack.appendChild(div);
    const t = setTimeout(() => {
      div.classList.add('out');
      setTimeout(() => { div.remove(); this.toastTimers.delete(t); }, 420);
    }, 3200);
    this.toastTimers.add(t);
    while (this.el.toastStack.children.length > 4) this.el.toastStack.firstElementChild.remove();
  }

  showBanner(zone) {
    this.el.bannerTitle.textContent = zone.name;
    this.el.bannerSub.textContent = `${zone.range} · ${zone.short}`;
    this.el.zoneBanner.classList.remove('is-hidden');
    requestAnimationFrame(() => this.el.zoneBanner.classList.add('is-visible'));
    clearTimeout(this.bannerTimer);
    this.bannerTimer = setTimeout(() => {
      this.el.zoneBanner.classList.remove('is-visible');
      setTimeout(() => this.el.zoneBanner.classList.add('is-hidden'), 420);
    }, 3400);
  }

  flashSave() {
    const el = this.el.saveIndicator;
    el.classList.add('show');
    clearTimeout(this.titleTimer);
    this.titleTimer = setTimeout(() => el.classList.remove('show'), 1300);
  }

  openFabricator() {
    this.el.fab.classList.remove('is-hidden');
    this.renderFabricator();
  }

  closeFabricator() {
    this.el.fab.classList.add('is-hidden');
  }

  openPause() {
    this.el.pause.classList.remove('is-hidden');
  }

  closePause() {
    this.el.pause.classList.add('is-hidden');
  }

  showGameOver({ depth, lost }) {
    this.el.gameover.classList.remove('is-hidden');
    this.el.overDepth.textContent = `${formatNumber(depth)} m`;
    this.el.overChests.textContent = `${this.game.openedChests.size} / ${TOTAL_CHESTS}`;
    this.el.overLost.textContent = `${formatNumber(lost)} scrap`;
  }

  hideGameOver() {
    this.el.gameover.classList.add('is-hidden');
  }

  showVictory({ depth }) {
    this.el.victory.classList.remove('is-hidden');
    this.el.victoryDepth.textContent = `${formatNumber(depth)} m`;
    this.el.victoryChests.textContent = `${this.game.openedChests.size} / ${TOTAL_CHESTS}`;
    this.el.victorySalvage.textContent = formatNumber(this.game.salvage);
  }

  hideVictory() {
    this.el.victory.classList.add('is-hidden');
  }

  setPauseStats() {
    const g = this.game;
    this.el.pauseDepth.textContent = `${formatNumber(depthAt(g.player.y))} m`;
    this.el.pauseChests.textContent = `${g.openedChests.size} / ${TOTAL_CHESTS}`;
    this.el.pauseTime.textContent = formatTime(g.stats.time);
  }

  renderFabricator() {
    const g = this.game;
    const el = this.el;
    el.fabSalvage.textContent = formatNumber(g.salvage);
    const stats = upgradesAt(g.upgrades);
    el.fabOxygen.textContent = `${stats.oxygen}`;
    el.fabHull.textContent = `${stats.health}`;
    el.fabSpeed.textContent = `${stats.speed}`;
    el.fabDepth.textContent = `${stats.pressure} m`;
    const repairCost = 20;
    const canRepair = g.player.health < g.player.healthMax && g.salvage >= repairCost;
    el.repairBtn.disabled = !canRepair;
    el.repairCost.textContent = g.player.health >= g.player.healthMax
      ? 'Hull at full integrity'
      : `${repairCost} scrap · +50 hull`;

    el.fabGrid.innerHTML = UPGRADES.map(up => {
      const level = g.upgrades[up.id] || 0;
      const maxed = level >= up.max;
      const cost = maxed ? 0 : up.costs[level];
      const affordable = !maxed && g.salvage >= cost;
      const current = up.values[Math.min(level, up.values.length - 1)];
      const next = up.values[Math.min(level + 1, up.values.length - 1)];
      const effect = maxed
        ? `${up.effect(current, current)} · maximum`
        : up.effect(current, next);
      const pips = Array.from({ length: up.max }, (_, i) => `<i class="${i < level ? 'on' : ''}"></i>`).join('');
      const buy = maxed
        ? `<button class="buy-btn" disabled>MAX</button>`
        : `<button class="buy-btn" data-buy="${up.id}" ${affordable ? '' : 'disabled'}>${svg('i-salvage')}${cost}</button>`;
      return `<article class="upgrade-card ${maxed ? 'maxed' : ''}">
        <div class="upgrade-head">
          <span class="upgrade-icon">${svg(up.icon)}</span>
          <div class="upgrade-title"><small>${up.code}</small><h3>${up.name}</h3></div>
          <span class="level-tag">LV ${level}/${up.max}</span>
        </div>
        <p class="upgrade-desc">${up.desc}</p>
        <div class="pips">${pips}</div>
        <div class="upgrade-foot">
          <span class="upgrade-effect">${effect}</span>
          ${buy}
        </div>
      </article>`;
    }).join('');
  }
}

