136: let paletteCache = new Map();
137: function blendPalette(a, b, t) {
138:   const key = `${a.top}${b.top}${t.toFixed(3)}`;
139:   if (paletteCache.has(key)) return paletteCache.get(key);
140:   const out = {};
141:   for (const k of ['top', 'mid', 'bottom', 'fog', 'accent', 'rim', 'rockTop', 'rockBottom', 'kelp', 'kelpDark', 'particle', 'jelly']) {
142:     out[k] = mixColor(a[k], b[k], t);
143:   }
144:   out.coral = a.coral.map((c, i) => mixColor(c, b.coral[i % b.coral.length], t));
145:   paletteCache.set(key, out);
146:   return out;
147: }
