149: export function paletteAt(y) {
150:   const zone = zoneAt(y);
151:   const idx = ZONES.indexOf(zone);
152:   const next = ZONES[idx + 1];
153:   const distanceToEnd = zone.end - y;
154:   if (next && distanceToEnd < 320) {
155:     return blendPalette(zone.palette, next.palette, smoothstep(1 - distanceToEnd / 320));
156:   }
157:   const prev = ZONES[idx - 1];
158:   const distanceFromStart = y - zone.start;
159:   if (prev && distanceFromStart < 320) {
160:     return blendPalette(prev.palette, zone.palette, smoothstep(distanceFromStart / 320));
161:   }
162:   return zone.palette;
163: }
