181: function makeReef(rng, x, y, scale, zone, opts = {}) {
182:   const lumps = [];
183:   const count = rng.int(4, 7);
184:   const spread = 150 * scale;
185:   for (let i = 0; i < count; i++) {
186:     const pos = count === 1 ? 0 : i / (count - 1) * 2 - 1;
187:     lumps.push({
188:       dx: pos * spread + rng.range(-28, 28) * scale,
189:       dy: rng.range(-38, 44) * scale - Math.abs(pos) * 9 * scale,
190:       rx: rng.range(42, 88) * scale,
191:       ry: rng.range(24, 62) * scale,
192:       rot: rng.range(-0.2, 0.2),
193:       tone: rng.next(),
194:     });
195:   }
196:   const plants = [];
197:   const plantCount = rng.int(2, 6);
198:   for (let i = 0; i < plantCount; i++) {
199:     const kind = rng.pick(['kelp', 'fan', 'branch', 'tube', 'anemone', 'whip']);
200:     plants.push({
201:       kind,
202:       dx: rng.range(-112, 112) * scale,
203:       dy: rng.range(-42, -6) * scale,
204:       size: rng.range(0.55, 1.25) * scale,
205:       hue: rng.int(0, zone.palette.coral.length - 1),
206:       phase: rng.range(0, Math.PI * 2),
207:       lean: rng.range(-0.2, 0.2),
208:     });
209:   }
210:   return {
211:     type: 'reef', x, y, scale, zone: zone.id, seed: rng.int(0, 999999), lumps, plants,
212:     collider: opts.collider === false ? null : { x, y: y - 8 * scale, rx: 128 * scale, ry: 64 * scale },
213:     layer: opts.layer || 'mid',
214:   };
215: }
