299:       const scale = rng.range(0.62, 1.65) * (zi === 3 ? 1.12 : 1);
300:       const reef = makeReef(rng, x, y, scale, zone, { layer: zi === 3 && i % 5 === 0 ? 'back' : 'mid' });
301:       if (reef.collider) colliders.push(reef.collider);
302:       decor.push(reef);
303:       if (i % 3 === 0) decor.push(makeCoral(rng, x + rng.range(-180, 180), y + rng.range(30, 90), rng.range(0.7, 1.6), zone));
304:       if (i % 4 === 0) decor.push(makeKelp(rng, x + rng.range(-160, 160), y + rng.range(30, 80), rng.range(0.7, 1.4), zone));
