315:       else if (roll < 0.88) decor.push(makeRuin(rng, x, y, rng.range(0.7, 1.4), zone, rng.pick(['columns', 'arch', 'slab'])));
316:       else decor.push(makeVent(rng, x, y, rng.range(0.75, 1.25), zone));
