64:         width: rng.range(1.2, 3.4),
65:         leaves: rng.int(3, 6),
66:         dark: rng.range(0.35, 0.85),
67:       });
68:     }
69:   }
70: 
71:   /* ---------- transforms and shared helpers ---------- */
72:   screen(x, y, p = 1) {
73:     const cam = this.camera;
74:     return [
75:       (x - cam.x * p) * this.zoom + this.W / 2 + cam.shakeX,
76:       (y - cam.y * p) * this.zoom + this.H / 2 + cam.shakeY,
77:     ];
78:   }
79: 
80:   visible(x, y, pad = 260, p = 1) {
81:     const [sx, sy] = this.screen(x, y, p);
82:     return sx > -pad && sx < this.W + pad && sy > -pad && sy < this.H + pad;
83:   }
84: 
85:   palFor(zoneId) {
86:     return (ZONE_BY_ID.get(zoneId) || ZONES[0]).palette;
87:   }
88: 
89:   getGlow(color) {
90:     let c = this.glowCache.get(color);
91:     if (c) return c;
92:     const size = 128;
93:     const cv = document.createElement('canvas');
94:     cv.width = size; cv.height = size;
95:     const g = cv.getContext('2d');
96:     const grad = g.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
97:     grad.addColorStop(0, rgba(color, 0.95));
98:     grad.addColorStop(0.24, rgba(color, 0.48));
99:     grad.addColorStop(0.58, rgba(color, 0.12));
100:     grad.addColorStop(1, rgba(color, 0));
101:     g.fillStyle = grad;
102:     g.fillRect(0, 0, size, size);
103:     this.glowCache.set(color, cv);
104:     return cv;
105:   }
106: 
107:   drawGlow(x, y, color, radius, alpha = 1) {
108:     const glow = this.getGlow(color);
109:     const ctx = this.ctx;
110:     ctx.save();
111:     ctx.globalAlpha = alpha;
112:     ctx.globalCompositeOperation = 'lighter';
113:     ctx.drawImage(glow, x - radius, y - radius, radius * 2, radius * 2);
114:     ctx.restore();
115:   }
116: 
117:   blobPath(cx, cy, rx, ry, seed, points = 13, rough = 0.17) {
118:     const ctx = this.ctx;
119:     ctx.beginPath();
120:     for (let i = 0; i < points; i++) {
121:       const a = (i / points) * TAU;
122:       const n = 1 + rough * (Math.sin(seed * 0.91 + i * 2.71) * 0.65 + Math.sin(seed * 1.73 + i * 5.13) * 0.35);
123:       const px = cx + Math.cos(a) * rx * n;
124:       const py = cy + Math.sin(a) * ry * n;
125:       if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
126:     }
127:     ctx.closePath();
128:   }
129: 
130:   roundRect(x, y, w, h, r) {
131:     const ctx = this.ctx;
132:     const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
133:     ctx.beginPath();
134:     ctx.moveTo(x + rr, y);
135:     ctx.arcTo(x + w, y, x + w, y + h, rr);
136:     ctx.arcTo(x + w, y + h, x, y + h, rr);
137:     ctx.arcTo(x, y + h, x, y, rr);
138:     ctx.arcTo(x, y, x + w, y, rr);
139:     ctx.closePath();
140:   }
141: 
142:   /* ---------- main draw ---------- */
143:   render(game) {
144:     const ctx = this.ctx;
145:     this.time = game.time;
146:     this.game = game;
147:     this.camera = game.camera;
148:     this.pal = paletteAt(game.camera.y);
149: 
150:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
151:     ctx.globalAlpha = 1;
152:     ctx.globalCompositeOperation = 'source-over';
153: 
154:     this.drawWater();
155:     this.drawBackdrop();
156:     this.drawRays();
157:     this.drawMotes();
158: 
159:     this.drawDecor('back');
160:     this.drawDecor('mid');
161: 
162:     for (const chest of game.chests) if (this.visible(chest.x, chest.y, 140)) drawChest(this, chest, game);
163:     for (const res of game.resources) if (!res.collected && this.visible(res.x, res.y, 100)) drawResource(this, res, game);
164: 
165:     this.drawHeadlightIfAny();
166: 
167:     const drawables = [];
168:     for (const c of game.creatures) {
169:       if (!this.visible(c.x, c.y, 340)) continue;
170:       drawables.push({ y: c.y, kind: 'creature', c });
171:     }
172:     if (game.mode !== 'title' || game.titleSub) {
173:       drawables.push({ y: game.player.y, kind: 'player' });
174:     }
175:     drawables.sort((a, b) => a.y - b.y);
176:     for (const d of drawables) {
177:       if (d.kind === 'creature') drawCreature(this, d.c);
178:       else drawPlayer(this, game);
179:     }
180: 
181:     this.drawBubbles(game.bubbles);
182:     this.drawDecor('fg');
183:     this.drawFrameFronds();
184:     this.drawParticles(game.particles);
185:     this.drawPulse(game);
186:     this.drawScreenFx(game);
187:   }
188: 
189:   drawHeadlightIfAny() {
190:     if (this.game.mode !== 'playing' && this.game.mode !== 'title') return;
191:     if (!this.game.player?.lightsOn) return;
192:     drawHeadlight(this, this.game);
193:   }
194: 
195:   /* ---------- water & atmosphere ---------- */
196:   drawWater() {
197:     const ctx = this.ctx, W = this.W, H = this.H, pal = this.pal;
198:     const zone = zoneAt(this.camera.y);
199:     const light = clamp(zone.light * (1 - clamp((this.camera.y - 500) / 6200, 0, 0.5)), 0, 1);
200:     const grad = ctx.createLinearGradient(0, 0, 0, H);
201:     grad.addColorStop(0, pal.top);
202:     grad.addColorStop(0.38, pal.mid);
203:     grad.addColorStop(0.74, mixColor(pal.mid, pal.bottom, 0.72));
204:     grad.addColorStop(1, pal.bottom);
205:     ctx.fillStyle = grad;
206:     ctx.fillRect(0, 0, W, H);
207: 
208:     // Broad surface bloom.
209:     if (light > 0.03) {
210:       ctx.save();
211:       ctx.globalCompositeOperation = 'screen';
212:       const glow = ctx.createRadialGradient(W * 0.5, -H * 0.12, 0, W * 0.5, -H * 0.12, H * 1.18);
213:       glow.addColorStop(0, rgba(pal.rim, 0.3 * light));
214:       glow.addColorStop(0.34, rgba(pal.fog, 0.11 * light));
215:       glow.addColorStop(1, rgba(pal.fog, 0));
216:       ctx.fillStyle = glow;
217:       ctx.fillRect(0, 0, W, H);
218:       ctx.restore();
219:     }
220: 
221:     // Cool rim at the edges of the water column.
222:     const side = ctx.createLinearGradient(0, 0, W, 0);
223:     side.addColorStop(0, 'rgba(0,5,12,.22)');
224:     side.addColorStop(0.15, 'rgba(0,5,12,0)');
225:     side.addColorStop(0.85, 'rgba(0,5,12,0)');
226:     side.addColorStop(1, 'rgba(0,5,12,.24)');
227:     ctx.fillStyle = side;
228:     ctx.fillRect(0, 0, W, H);
229: 
230:     this.drawSurface();
231:     this.drawBioHaze();
232:   }
233: 
234:   drawSurface() {
235:     const ctx = this.ctx;
236:     const sy = (WORLD.surface - this.camera.y) * this.zoom + this.H / 2 + this.camera.shakeY;
237:     if (sy < -90 || sy > this.H * 0.72) return;
238:     const sky = ctx.createLinearGradient(0, Math.min(-200, sy - 300), 0, sy + 10);
239:     sky.addColorStop(0, '#c4f5fa');
240:     sky.addColorStop(0.62, '#8fe3ee');
241:     sky.addColorStop(1, '#63c8dc');
242:     ctx.fillStyle = sky;
243:     ctx.fillRect(0, -400, this.W, Math.max(0, sy + 400));
244:     ctx.save();
245:     ctx.globalCompositeOperation = 'screen';
246:     for (let i = 0; i < 5; i++) {
247:       const y = sy - (i + 1) * 14;
248:       ctx.beginPath();
249:       for (let x = -20; x <= this.W + 20; x += 20) {
250:         const yy = y + Math.sin(x * 0.018 + this.time * 1.2 + i * 1.3) * (7 - i * 0.8);
251:         if (x === -20) ctx.moveTo(x, yy); else ctx.lineTo(x, yy);
252:       }
253:       ctx.strokeStyle = `rgba(226,255,255,${0.26 - i * 0.04})`;
254:       ctx.lineWidth = 1.4;
255:       ctx.stroke();
256:     }
257:     const glint = ctx.createLinearGradient(0, sy - 120, 0, sy + 20);
258:     glint.addColorStop(0, 'rgba(226,255,255,0)');
259:     glint.addColorStop(0.6, 'rgba(226,255,255,.13)');
260:     glint.addColorStop(1, 'rgba(120,240,238,.2)');
261:     ctx.fillStyle = glint;
262:     ctx.fillRect(0, sy - 120, this.W, 135);
263:     ctx.restore();
264:   }
265: 
266:   drawBioHaze() {
267:     if (this.camera.y < 2400) return;
268:     const ctx = this.ctx, W = this.W, H = this.H, pal = this.pal;
269:     ctx.save();
270:     ctx.globalCompositeOperation = 'screen';
271:     for (let i = 0; i < 3; i++) {
272:       const x = W * (0.2 + i * 0.32) + Math.sin(this.time * 0.05 + i * 2.2) * 90;
273:       const y = H * (0.32 + 0.2 * Math.sin(i * 2.7 + this.time * 0.03));
274:       const r = H * (0.34 + i * 0.12);
275:       const g = ctx.createRadialGradient(x, y, 0, x, y, r);
276:       g.addColorStop(0, rgba(pal.accent, 0.035));
277:       g.addColorStop(0.5, rgba(pal.fog, 0.018));
278:       g.addColorStop(1, rgba(pal.fog, 0));
279:       ctx.fillStyle = g;
280:       ctx.fillRect(0, 0, W, H);
281:     }
282:     ctx.restore();
283:   }
284: 
285:   drawBackdrop() {
286:     this.drawCanyon();
287:     this.drawDistantRidges();
288: 
289:     for (const jelly of this.game.world.ambientJellies) {
290:       if (!this.visible(jelly.x, jelly.y, 300, jelly.parallax)) continue;
291:       drawAmbientJelly(this, jelly);
292:     }
293: 
294:     // A very distant survey whale, only in the deeper half of the ocean.
295:     if (this.camera.y > 2500) this.drawWhale();
296:   }
297: 
298:   drawCanyon() {
299:     const ctx = this.ctx, W = this.W, H = this.H, pal = this.pal;
300:     const camY = this.camera.y, camX = this.camera.x;
301:     const drawWall = (side, layers) => {
302:       for (const layer of layers) {
303:         const pts = [];
304:         const steps = 18;
305:         for (let i = 0; i <= steps; i++) {
306:           const yy = i / steps * H;
307:           const worldY = camY - H / 2 + yy;
308:           const n = wobble(worldY * 0.012 + side * 13.7, side * 2.3 + layer.seed);
309:           const bulge = Math.sin(worldY * 0.0021 + layer.seed) * layer.amp * 0.45;
310:           const edge = layer.base + (n * 0.5 + 0.5) * layer.amp + bulge + (camX - WORLD.spawn.x) * 0.018;
311:           const x = side < 0 ? edge * W : W - edge * W;
312:           pts.push([x, yy]);
313:         }
314:         ctx.beginPath();
315:         if (side < 0) {
316:           ctx.moveTo(-5, -5);
317:           for (const [x, y] of pts) ctx.lineTo(x, y);
318:           ctx.lineTo(-5, H + 5);
319:         } else {
320:           ctx.moveTo(W + 5, -5);
321:           for (const [x, y] of pts) ctx.lineTo(x, y);
322:           ctx.lineTo(W + 5, H + 5);
323:         }
324:         ctx.closePath();
325:         const g = ctx.createLinearGradient(side < 0 ? 0 : W, 0, side < 0 ? W * 0.3 : W * 0.7, 0);
326:         g.addColorStop(0, rgba(layer.color, layer.alpha));
327:         g.addColorStop(0.55, rgba(layer.color, layer.alpha * 0.62));
328:         g.addColorStop(1, rgba(layer.color, 0));
329:         ctx.fillStyle = g;
330:         ctx.fill();
331: 
332:         // Rim lighting along the jagged edge.
333:         if (layer.rim > 0) {
334:           ctx.beginPath();
335:           pts.forEach(([x, y], i) => { if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y); });
336:           ctx.strokeStyle = rgba(pal.rim, layer.rim);
337:           ctx.lineWidth = 1.4;
338:           ctx.stroke();
339:         }
340: 
341:         // Little rock shelves and cold bioluminescence on the wall.
342:         if (layer.shelves) {
343:           for (let i = 1; i < pts.length - 1; i += 3) {
344:             const [x, y] = pts[i];
345:             const w = (side < 0 ? 1 : -1) * (12 + (i % 4) * 9);
346:             ctx.beginPath();
347:             ctx.moveTo(x, y + 2);
348:             ctx.lineTo(x - w * 0.75, y + 20);
349:             ctx.lineTo(x - w * 0.1, y + 13);
350:             ctx.closePath();
351:             ctx.fillStyle = rgba(layer.color, layer.alpha * 0.65);
352:             ctx.fill();
353:             if ((i + layer.seed) % 5 === 0) {
354:               const gx = x + (side < 0 ? 16 : -16);
355:               const gy = y + 26;
356:               ctx.fillStyle = rgba(pal.accent, 0.24);
357:               ctx.beginPath(); ctx.arc(gx, gy, 1.6, 0, TAU); ctx.fill();
358:               if (this.camera.y > 2800) this.drawGlow(gx, gy, pal.accent, 12, 0.4);
359:             }
360:           }
361:         }
362:       }
363:     };
364: 
365:     const fog = mixColor(pal.fog, pal.bottom, 0.55);
366:     const near = mixColor(pal.rockBottom, '#000000', 0.22);
367:     drawWall(-1, [
368:       { base: 0.13, amp: 0.055, color: fog, alpha: 0.24, rim: 0.035, seed: 1.1, shelves: false },
369:       { base: 0.075, amp: 0.05, color: near, alpha: 0.55, rim: 0.07, seed: 4.4, shelves: true },
370:     ]);
371:     drawWall(1, [
372:       { base: 0.16, amp: 0.06, color: fog, alpha: 0.2, rim: 0.03, seed: 7.7, shelves: false },
373:       { base: 0.086, amp: 0.045, color: near, alpha: 0.52, rim: 0.065, seed: 2.8, shelves: true },
374:     ]);
375:   }
376: 
377:   drawDistantRidges() {
378:     const ctx = this.ctx, W = this.W, H = this.H, pal = this.pal;
379:     const drawRidge = (baseline, amp, color, alpha, seed) => {
380:       ctx.beginPath();
381:       ctx.moveTo(-20, H + 30);
382:       for (let x = -20; x <= W + 20; x += 26) {
383:         const wx = this.camera.x + (x - W / 2) / this.zoom;
384:         const n = wobble(wx * 0.006 + seed, seed * 1.7) * 0.5 + 0.5;
385:         const sway = Math.sin(this.camera.y * 0.0008 + seed) * 22;
386:         const y = baseline - n * amp + sway;
387:         ctx.lineTo(x, y);
388:       }
389:       ctx.lineTo(W + 20, H + 30);
390:       ctx.closePath();
391:       ctx.fillStyle = rgba(color, alpha);
392:       ctx.fill();
393:     };
394:     drawRidge(H * 0.88, H * 0.3, mixColor(pal.rockBottom, '#000', 0.15), 0.3, 2.2);
395:     drawRidge(H * 0.94, H * 0.25, mixColor(pal.rockBottom, '#000', 0.4), 0.45, 5.1);
396: 
397:     // Slow, enormous whale silhouette.
398:   }
399: 
400:   drawWhale() {
401:     const ctx = this.ctx, W = this.W;
402:     const t = this.time * 0.008;
403:     const x = ((t * 40 + 260) % (W + 1100)) - 500;
404:     const y = this.H * 0.28 + Math.sin(this.time * 0.07) * 26;
405:     ctx.save();
406:     ctx.translate(x, y);
407:     ctx.scale(1.4, 1.4);
408:     ctx.globalAlpha = 0.045;
409:     ctx.fillStyle = '#04121f';
410:     ctx.beginPath();
411:     ctx.moveTo(-180, 0);
412:     ctx.bezierCurveTo(-120, -36, 80, -44, 170, -8);
413:     ctx.bezierCurveTo(196, 2, 188, 18, 150, 22);
414:     ctx.bezierCurveTo(40, 32, -90, 26, -180, 8);
415:     ctx.closePath();
416:     ctx.fill();
417:     ctx.beginPath();
418:     ctx.moveTo(160, -4); ctx.lineTo(208, -30); ctx.lineTo(198, 18); ctx.closePath();
419:     ctx.fill();
420:     ctx.restore();
421:   }
422: 
423:   drawRays() {
424:     const ctx = this.ctx, W = this.W, H = this.H, pal = this.pal;
425:     const zone = zoneAt(this.camera.y);
426:     const light = zone.light * clamp(1 - (this.camera.y - 300) / 5200, 0, 1);
427:     if (light < 0.035) return;
428:     ctx.save();
429:     ctx.globalCompositeOperation = 'screen';
430:     const count = 7;
431:     for (let i = 0; i < count; i++) {
432:       const base = (i + 0.4) / count * W + Math.sin(this.time * 0.055 + i * 1.73) * 28;
433:       const topW = 14 + (i % 3) * 10;
434:       const botW = 130 + (i % 4) * 48;
435:       const tilt = 150 + i * 16;
436:       const alpha = (0.04 + 0.05 * (0.5 + 0.5 * Math.sin(this.time * 0.23 + i * 2.1))) * light;
437:       const g = ctx.createLinearGradient(base, -30, base + tilt, H);
438:       g.addColorStop(0, rgba(pal.rim, alpha * 1.8));
439:       g.addColorStop(0.4, rgba(pal.rim, alpha * 0.7));
440:       g.addColorStop(1, rgba(pal.rim, 0));
441:       ctx.fillStyle = g;
442:       ctx.beginPath();
443:       ctx.moveTo(base - topW, -40);
444:       ctx.lineTo(base + topW, -40);
445:       ctx.lineTo(base + tilt + botW, H + 40);
446:       ctx.lineTo(base + tilt - botW, H + 40);
447:       ctx.closePath();
448:       ctx.fill();
449:     }
450:     // Caustic ribbons just below the sun.
451:     if (this.camera.y < 1700) {
452:       for (let i = 0; i < 4; i++) {
453:         ctx.beginPath();
454:         for (let x = -20; x <= W + 20; x += 24) {
455:           const y = H * (0.08 + i * 0.07) + Math.sin(x * 0.011 + this.time * 0.6 + i * 1.9) * 13 + Math.sin(x * 0.03 - this.time * 0.4) * 4;
456:           if (x === -20) ctx.moveTo(x, y); else ctx.lineTo(x, y);
457:         }
458:         ctx.strokeStyle = rgba(pal.rim, 0.02 * light);
459:         ctx.lineWidth = 1.2;
460:         ctx.stroke();
461:       }
462:     }
463:     ctx.restore();
464:   }
465: 
466:   drawMotes() {
467:     const ctx = this.ctx, W = this.W, H = this.H, pal = this.pal;
468:     const deep = clamp((this.camera.y - 1800) / 3400, 0, 1);
469:     const cam = this.camera;
470:     ctx.save();
471:     for (const m of this.motes) {
472:       const drift = this.time * m.speed;
473:       const x = ((m.x * W + drift * 5 + Math.sin(this.time * 0.24 + m.phase) * 14 - cam.x * 0.018 * m.z) % (W + 60) + W + 60) % (W + 60) - 30;
474:       const y = ((m.y * H + drift * 3.2 + Math.sin(this.time * 0.17 + m.phase * 2) * 9 - cam.y * 0.035 * m.z) % (H + 60) + H + 60) % (H + 60) - 30;
475:       const a = (0.1 + 0.42 * m.z) * (0.45 + deep * 0.55);
476:       const col = deep > 0.35 ? (m.glow ? pal.accent : pal.particle) : pal.particle;
477:       ctx.fillStyle = rgba(col, a);
478:       ctx.beginPath();
479:       ctx.arc(x, y, m.size * (0.55 + m.z * 0.75), 0, TAU);
480:       ctx.fill();
481:       if (m.glow && deep > 0.3) this.drawGlow(x, y, col, 10 + m.z * 12, a * 0.55);
482:     }
483:     ctx.restore();
484:   }
485: 
486:   /* ---------- scenery ---------- */
487:   drawDecor(layer) {
488:     const list = this.game.world.decor;
489:     const p = layer === 'fg' ? 1.055 : layer === 'back' ? 0.992 : 1;
490:     const visible = [];
491:     for (const obj of list) {
492:       if ((obj.layer || 'mid') !== layer) continue;
493:       if (!this.visible(obj.x, obj.y, layer === 'fg' ? 420 : 300, p)) continue;
494:       visible.push(obj);
495:     }
496:     visible.sort((a, b) => a.y - b.y);
497:     if (layer === 'fg') this.ctx.save();
498:     for (const obj of visible) {
499:       switch (obj.type) {
500:         case 'reef': drawReef(this, obj, p, layer === 'fg'); break;
501:         case 'kelp': drawKelp(this, obj, p, layer === 'fg'); break;
502:         case 'coral': drawCoral(this, obj, p); break;
503:         case 'vent': drawVent(this, obj, p); break;
504:         case 'ruin': drawRuin(this, obj, p); break;
505:         case 'beacon': drawBeacon(this, obj, p); break;
506:         default: break;
507:       }
508:     }
509:     if (layer === 'fg') this.ctx.restore();
510:   }
511: 
512:   drawBubbles(bubbles) {
513:     const ctx = this.ctx;
514:     for (const b of bubbles) {
515:       const [sx, sy] = this.screen(b.x, b.y);
516:       if (sx < -30 || sx > this.W + 30 || sy < -30 || sy > this.H + 30) continue;
517:       const r = Math.max(0.7, b.r * this.zoom);
518:       const a = clamp(b.life / b.maxLife, 0, 1) * (b.alpha ?? 0.65);
519:       ctx.save();
520:       ctx.globalAlpha = a;
521:       ctx.beginPath();
522:       ctx.arc(sx, sy, r, 0, TAU);
523:       ctx.fillStyle = b.kind === 'spark' ? rgba(b.color || '#c9ffff', 0.12) : 'rgba(185,245,255,0.08)';
524:       ctx.fill();
525:       ctx.strokeStyle = b.color ? rgba(b.color, 0.55) : 'rgba(210,252,255,0.5)';
526:       ctx.lineWidth = Math.max(0.7, r * 0.16);
527:       ctx.stroke();
528:       ctx.beginPath();
529:       ctx.arc(sx - r * 0.3, sy - r * 0.35, Math.max(0.4, r * 0.2), 0, TAU);
530:       ctx.fillStyle = 'rgba(255,255,255,.7)';
531:       ctx.fill();
532:       ctx.restore();
533:     }
534:   }
535: 
536:   drawParticles(particles) {
537:     const ctx = this.ctx;
538:     for (const p of particles) {
