import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions });
for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
  const page = await browser.newPage({ viewport: { width, height } });
  const errors = [];
  page.on('pageerror', e => { errors.push(e.stack || e.message); console.log('PAGEERROR', e.message); });
  page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
  await page.goto('http://localhost:3000', { waitUntil: 'load' });
  await page.waitForFunction(() => document.fonts.status === 'loaded');
  await page.screenshot({ path: `${out}/title-${name}.png` });
  const start = page.locator('#start-btn');
  await start.click();
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `${out}/game-${name}.png` });
  const info = await page.evaluate(() => {
    const g = window.deepOcean;
    return {
      mode: g.mode, player: { x: g.player.x, y: g.player.y, o2: g.player.oxygen, hp: g.player.health },
      zone: g.currentZone.id, salvage: g.salvage, chests: g.openedChests.size,
      creatures: g.creatures.length, resources: g.resources.length,
      colliders: g.world.colliders.length, decor: g.world.decor.length,
      camera: g.camera, fps: g.fps,
    };
  });
  console.log(name, JSON.stringify(info));
  console.log(name, 'errors', errors.length);
  await page.close();
}
await browser.close();

