import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.locator('#start-btn').click();
await page.waitForTimeout(800);
const info = await page.evaluate(() => {
  const g = window.deepOcean, r = g.renderer;
  const vis = [];
  for (const d of g.world.decor) {
    const [sx, sy] = r.screen(d.x, d.y);
    if (sx > -400 && sx < r.W + 400 && sy > -400 && sy < r.H + 400) vis.push({ type: d.type, variant: d.variant, layer: d.layer, x: Math.round(d.x), y: Math.round(d.y), scale: d.scale, sx: Math.round(sx), sy: Math.round(sy) });
  }
  return vis;
});
console.log(JSON.stringify(info, null, 1));
await page.screenshot({ path: `${out}/crop-raw.png`, clip: { x: 580, y: 0, width: 720, height: 560 } });
// isolate: no ruins
await page.evaluate(() => { const g = window.deepOcean; g.world.decor = g.world.decor.filter(d => d.type !== 'ruin'); });
await page.waitForTimeout(100);
await page.screenshot({ path: `${out}/no-ruins.png` });
// no reefs
await page.evaluate(() => { const g = window.deepOcean; g.world.decor = g.world.decor.filter(d => d.type !== 'reef'); });
await page.waitForTimeout(100);
await page.screenshot({ path: `${out}/no-ruins-reefs.png` });
// only mid vs etc expensive; leave
await browser.close();

import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.locator('#start-btn').click();
await page.waitForTimeout(500);
for (const mode of ['none', 'reef', 'kelp', 'coral', 'ruin', 'vent']) {
  await page.evaluate((mode) => {
    const g = window.deepOcean;
    if (!g._allDecor) g._allDecor = g.world.decor;
    g.world.decor = mode === 'none' ? [] : g._allDecor.filter(d => d.type === mode);
    g.world.creatures = [];
    g.resources = [];
  }, mode);
  await page.waitForTimeout(120);
  await page.screenshot({ path: `${out}/only-${mode}.png` });
}
await browser.close();

