await page.locator('#start-btn').click();
await page.waitForTimeout(300);
const res = await page.evaluate(async () => {
  const g = window.deepOcean;
  const out = {
    sameWorld: g.world === g.renderer.game.world,
    sameDecor: g.world.decor === g.renderer.game.world.decor,
    gameIsGame: g === g.renderer.game,
    canvases: document.querySelectorAll('canvas').length,
    mainEntries: performance.getEntriesByType('resource').filter(e => e.name.includes('main.js')).map(e => e.name),
    decor: g.world.decor.length,
    rendererDecor: g.renderer.game.world.decor.length,
    rafCount: 0,
    renderCount: 0,
  };
  const origRender = g.renderer.render;
  g.renderer.render = function (game) { out.renderCount++; return origRender.call(this, game); };
  const origRaf = window.requestAnimationFrame;
  window.requestAnimationFrame = function (cb) { out.rafCount++; return origRaf.call(window, cb); };
  await new Promise(r => setTimeout(r, 500));
  window.requestAnimationFrame = origRaf;
  g.renderer.render = origRender;
  return out;
});
