import { createRequire } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/tmp/opencode/shots';
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => console.log('CONSOLE', m.text()));
await page.goto('http://localhost:3000', { waitUntil: 'load' });
const info = await page.evaluate(async () => {
  const mod = await import('/js/render-environment.js');
  const { ZONES } = await import('/js/world.js');
  const g = window.deepOcean;
  const reef = g.world.decor.find(d => d.type === 'reef');
  const cv = document.createElement('canvas');
  cv.width = 1440; cv.height = 900;
  document.body.appendChild(cv);
  cv.style.cssText = 'position:fixed;inset:0;z-index:99999';
  const ctx = cv.getContext('2d');
  const stub = {
    ctx, W: 1440, H: 900, zoom: 1, time: 1.5,
    camera: { x: 0, y: 0, shakeX: 0, shakeY: 0 },
    pal: ZONES[0].palette,
    screen(x, y, p = 1) { return [700 + x, 500 + y]; },
    palFor() { return ZONES[0].palette; },
    blobPath(cx, cy, rx, ry, seed, points = 13, rough = 0.17) {
      ctx.beginPath();
      for (let i = 0; i < points; i++) {
        const a = (i / points) * Math.PI * 2;
        const n = 1 + rough * (Math.sin(seed * 0.91 + i * 2.71) * 0.65 + Math.sin(seed * 1.73 + i * 5.13) * 0.35);
        const px = cx + Math.cos(a) * rx * n, py = cy + Math.sin(a) * ry * n;
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath();
    },
    roundRect(x, y, w, h, r) {
      ctx.beginPath();
      ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r);
      ctx.arcTo(x + w, y + h, x, y + h, r); ctx.arcTo(x, y + h, x, y, r);
      ctx.arcTo(x, y, x + w, y, r); ctx.closePath();
    },
    drawGlow(x, y, color, radius, alpha = 1) {},
  };
  ctx.fillStyle = '#204050'; ctx.fillRect(0, 0, 1440, 900);
  mod.drawReef(stub, reef, 1, false);
  const t = ctx.getTransform();
  return { reef: { x: reef.x, y: reef.y, scale: reef.scale, zone: reef.zone, lumps: reef.lumps.length, plants: reef.plants.length }, transform: { a: t.a, b: t.b, c: t.c, d: t.d, e: t.e, f: t.f }, data: cv.toDataURL('image/png') };
});
console.log(JSON.stringify({ reef: info.reef, transform: info.transform }));
writeFileSync(`${out}/reef-fresh.png`, Buffer.from(info.data.split(',')[1], 'base64'));
await browser.close();

