import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.locator('#start-btn').click();
await page.waitForTimeout(800);
const info = await page.evaluate(() => {
  const g = window.deepOcean, r = g.renderer, cam = g.camera;
  const out = { zoom: r.zoom, cam: { ...cam }, items: [] };
  for (const d of g.world.decor) {
    const [sx, sy] = r.screen(d.x, d.y);
    if (sx > -500 && sx < 700 && sy > 400 && sy < 900) {
      out.items.push({ type: d.type, x: d.x, y: d.y, scale: d.scale, layer: d.layer, sx: Math.round(sx), sy: Math.round(sy), lumps: d.lumps?.length, variant: d.variant, seed: d.seed });
    }
  }
  out.enemies = g.creatures.filter(c => r.screen(c.x, c.y)[0] < 700 && r.screen(c.x, c.y)[1] > 400);
  return out;
});
console.log(JSON.stringify(info, null, 1));
await page.screenshot({ path: '/tmp/opencode/shots/crop-dark.png', clip: { x: 80, y: 500, width: 480, height: 340 } });
await browser.close();

