import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.locator('#start-btn').click();
await page.waitForTimeout(800);
const clip = { x: 120, y: 560, width: 360, height: 240 };
for (const type of ['none', 'ruin', 'reef', 'kelp', 'coral', 'vent', 'all']) {
  await page.evaluate((type) => {
    const g = window.deepOcean;
    if (!window.__origDecor) window.__origDecor = g.world.decor.slice();
    g.world.decor = type === 'all' || type === 'none' ? window.__origDecor.slice() : window.__origDecor.filter(d => d.type !== type);
  }, type);
  await page.waitForTimeout(600);
  await page.screenshot({ path: `/tmp/opencode/shots/hide-${type}.png`, clip });
}
await page.evaluate(() => { window.deepOcean.world.decor = window.__origDecor; });
await browser.close();

