import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.locator('#start-btn').click();
await page.waitForTimeout(500);
const probe = await page.evaluate(async () => {
  const out = {};
  out.lowFx = document.documentElement.classList.contains('low-fx');
  try {
    const probe = document.createElement('canvas');
    const gl = probe.getContext('webgl');
    const ext = gl && gl.getExtension('WEBGL_debug_renderer_info');
    out.gl = ext ? String(gl.getParameter(ext.UNMASKED_RENDERER_WEBGL)) : 'no-ext';
  } catch (e) { out.gl = 'err ' + e.message; }
  out.dpr = window.devicePixelRatio;
  out.canvas = { w: document.getElementById('scene').width, h: document.getElementById('scene').height };
  const t0 = performance.now();
  let n = 0;
  await new Promise(res => {
    const step = () => { n++; if (performance.now() - t0 > 2000) res(); else requestAnimationFrame(step); };
    requestAnimationFrame(step);
  });
  out.fps = +(n / ((performance.now() - t0) / 1000)).toFixed(2);
  out.measure = await page.evaluate(() => ({ r: window.deepOcean.renderer.dpr }));
  return out;
});
console.log(JSON.stringify(probe, null, 1));
await browser.close();

