const res = await page.evaluate(async () => {
  const g = window.deepOcean, r = g.renderer;
  const names = ['drawWater', 'drawBackdrop', 'drawRays', 'drawMotes', 'drawDecor', 'drawCreatures', 'drawPlayer', 'drawBubbles', 'drawParticles', 'drawPulse', 'drawScreenFx', 'drawFrameFronds'];
  const acc = {};
  for (const n of names) {
    if (typeof r[n] !== 'function') { acc[n] = 'missing'; continue; }
    const orig = r[n].bind(r);
    r[n] = (...a) => { const t = performance.now(); const v = orig(...a); acc[n] = (acc[n] || 0) + performance.now() - t; return v; };
  }
  const origRender = r.render.bind(r);
  let renderTotal = 0, updates = 0, renders = 0;
  const origUpdate = g.update.bind(g);
  g.update = (...a) => { const t = performance.now(); const v = origUpdate(...a); updates += performance.now() - t; return v; };
  r.render = (...a) => { const t = performance.now(); const v = origRender(...a); renderTotal += performance.now() - t; renders++; return v; };
  const t0 = performance.now();
  let frames = 0;
  await new Promise(res => {
    const step = () => {
      frames++;
      if (performance.now() - t0 > 4000) res();
      else requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  });
  const wall = performance.now() - t0;
  const round = o => Object.fromEntries(Object.entries(o).map(([k, v]) => [k, typeof v === 'number' ? +v.toFixed(1) : v]));
  return { frames, wall: +wall.toFixed(0), renderTotal: +renderTotal.toFixed(0), updates: +updates.toFixed(0), renders, acc: round(acc), mode: g.mode, ramp: g.world.decor.length };
});
