import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message); });
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.locator('#start-btn').click();
await page.waitForTimeout(700);
const log = (l, v) => console.log(l, JSON.stringify(v));

// resource collection
log('res-before', await page.evaluate(() => {
  const g = window.deepOcean;
  const r = g.resources.find(r => !r.collected && r.type === 'scrap');
  g.player.x = r.x; g.player.y = r.y;
  return { salvage: g.salvage, target: r.id, dist: 0 };
}));
await page.waitForTimeout(900);
log('res-after', await page.evaluate(() => { const g = window.deepOcean; return { salvage: g.salvage, collected: g.collected.size, stats: g.stats.resources }; }));

// oxygen pickup
log('oxygen-pickup', await page.evaluate(() => {
  const g = window.deepOcean;
  g.player.oxygen = 30;
  const r = g.resources.find(r => r.type === 'oxygen' && !r.collected);
  g.player.x = r.x; g.player.y = r.y;
  return { before: 30, target: r.id };
}));
await page.waitForTimeout(900);
log('oxygen-after', await page.evaluate(() => { const g = window.deepOcean; return { o2: Math.round(g.player.oxygen), max: g.player.oxygenMax }; }));

// open every chest
for (let i = 0; i < 7; i++) {
  const state = await page.evaluate((i) => {
    const g = window.deepOcean;
    const c = g.chests[i];
    g.player.x = c.x; g.player.y = c.y; g.player.vx = g.player.vy = 0;
    g.camera.x = c.x; g.camera.y = c.y;
    g.player.invulnerable = 99; g.player.oxygen = g.player.oxygenMax; g.player.health = g.player.healthMax;
    return { id: c.id, opened: c.opened, mode: g.mode, z: c.zone };
  }, i);
  await page.waitForTimeout(350);
  await page.keyboard.press('KeyE');
  await page.waitForTimeout(350);
  const after = await page.evaluate(() => { const g = window.deepOcean; return { mode: g.mode, chests: g.openedChests.size, salvage: g.salvage }; });
  console.log('chest', i, state.id, JSON.stringify(after));
  if (after.mode === 'victory') break;
}
await page.waitForTimeout(600);
log('victory-state', await page.evaluate(() => {
  const g = window.deepOcean;
  return { mode: g.mode, completed: g.completed, overlay: !document.getElementById('victory-screen').classList.contains('is-hidden'), chests: g.openedChests.size };
}));
await page.screenshot({ path: '/tmp/opencode/shots/victory.png' });
if (await page.evaluate(() => window.deepOcean.mode === 'victory')) {
  await page.locator('#victory-continue').click();
  await page.waitForTimeout(400);
  log('victory-continue', await page.evaluate(() => ({ mode: window.deepOcean.mode, completed: window.deepOcean.completed })));
}
console.log('errors', errors.length);
await browser.close();

